        )
        checks.check(
            "filter-order-invariant",
            first == second == {"P0", "P2"},
            expected=["P0", "P2"],
            observed=sorted(first or []),
        )
        checks.refuses(
            "unknown-filter-refused",
            UsageRefused,
            lambda: v2_parse_csv_set(
                "P9",
                allowed={"P0"},
                label="priorities",
            ),
            contains="unknown",
        )
        review, authority, _ = v2_plan_for_count(
            2,
            max_targets=V2_REVIEW_TARGET_DEFAULT,
        )
        selected_target = review["children"][0]["target_ids"][0]
        filtered_target = next(
            row["target_id"]
            for row in authority["decisions"]
            if row["target_id"] != selected_target
        )
        selected_review = {
            "children": [
                {
                    "priority": 2,
