    elif slug in {"ux-empty-synopsis", "ux-large-synopsis"}:
        count = 0 if slug == "ux-empty-synopsis" else 13
        inventory = v2_synthetic_inventory(
            [v2_synthetic_target(index) for index in range(count)]
