                "counts": {"zero_receipts": 25 if not count else 24},
            }
        )
        synopsis = v2_synopsis(
            subject_mode="review-plan",
            review_plan=review,
            history=history,
            authority=authority,
            zero_sets=zero,
            artifact_dir="target/v2/fixture",
            reproduction=["script", "--review-plan"],
            explain_target=None,
        )
        checks.check(
            "synopsis-bounded-utf8",
            len(canonical_bytes(synopsis)) <= V2_SYNOPSIS_BYTES_CAP,
            expected=f"<= {V2_SYNOPSIS_BYTES_CAP}",
            observed=len(canonical_bytes(synopsis)),
        )
        checks.check(
            "synopsis-id-preview",
            synopsis["selected_ids"]["shown"] == min(count, 12)
            and synopsis["selected_ids"]["total"] == count,
            expected={"shown": min(count, 12), "total": count},
            observed=synopsis["selected_ids"],
        )
        if count:
            checks.check(
                "synopsis-truncation-explicit",
                synopsis["selected_ids"]["truncated"] is True
                and synopsis["selected_ids"]["notice"] is not None,
                expected=True,
                observed=synopsis["selected_ids"],
            )
    elif slug == "ux-streams-color-tty":
        document = {
            "terminal": "Pass",
            "no_color": True,
            "tty_independent": True,
        }
        encoded = canonical_bytes(document)
        checks.check(
            "no-ansi",
            b"\x1b[" not in encoded,
            expected="no ANSI escape",
            observed="absent" if b"\x1b[" not in encoded else "present",
        )
        checks.check(
            "semantic-stream-determinism",
            encoded == canonical_bytes(dict(reversed(list(document.items())))),
            expected=text_root(encoded.decode("utf-8")),
            observed=text_root(
                canonical_bytes(dict(reversed(list(document.items())))).decode("utf-8")
            ),
        )
    elif slug == "compat-v1-immutable":
        v1 = load_case_manifest()
        compatibility = manifest["compatibility_contract"]
        payload = bounded_read(REPO_ROOT / CASE_MANIFEST_REL)
        retained_manifest_blob = run_command(
            [
                "git",
                "rev-parse",
                (
                    compatibility["v1_manifest_adopted_git_commit"]
                    + ":"
                    + compatibility["v1_manifest_path"]
                ),
            ],
            record_global_receipt=False,
        ).stdout.strip()
        checks.check(
            "v1-content-root",
            "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            == compatibility["v1_manifest_content_root"],
            expected=compatibility["v1_manifest_content_root"],
            observed="sha256-v1:" + hashlib.sha256(payload).hexdigest(),
        )
        checks.check(
            "v1-semantic-root",
            v1["semantic_root"]
            == compatibility["v1_case_manifest_semantic_root"],
            expected=compatibility["v1_case_manifest_semantic_root"],
            observed=v1["semantic_root"],
        )
        checks.check(
            "v1-registry-counts",
            len(v1["case"]) == 21
            and compatibility["v1_assertion_count"] == 148,
            expected={"cases": 21, "assertions": 148},
            observed={
                "cases": len(v1["case"]),
                "assertions": compatibility["v1_assertion_count"],
            },
        )
        checks.check(
            "v1-manifest-baseline-portably-retained",
            retained_manifest_blob
            == compatibility["v1_manifest_adopted_git_blob"]
            and compatibility["v1_manifest_blob_retention"]
            == "REACHABLE_COMMIT_PATH_IDENTITY",
            expected={
                "blob": compatibility["v1_manifest_adopted_git_blob"],
                "retention": "REACHABLE_COMMIT_PATH_IDENTITY",
            },
            observed={
                "blob": retained_manifest_blob,
                "retention": compatibility[
                    "v1_manifest_blob_retention"
                ],
            },
        )
        checks.check(
            "nonportable-adoption-evidence-is-explicit-nodata",
            compatibility["v1_harness_blob_retention"]
            == "UNREACHABLE_LOCAL_OBJECT_NODATA"
            and compatibility["adoption_artifact_retention"]
            == "IGNORED_LOCAL_ONLY_NODATA"
            and compatibility["portable_adoption_evidence"] is False
            and compatibility["compatibility_proof_authority"]
            == "CURRENT_V1_MANIFEST_AND_RUNTIME_REGRESSION_ONLY",
            expected={
                "harness": "UNREACHABLE_LOCAL_OBJECT_NODATA",
                "artifact": "IGNORED_LOCAL_ONLY_NODATA",
                "portable": False,
                "authority": (
                    "CURRENT_V1_MANIFEST_AND_RUNTIME_REGRESSION_ONLY"
                ),
            },
            observed={
                "harness": compatibility[
                    "v1_harness_blob_retention"
                ],
                "artifact": compatibility[
                    "adoption_artifact_retention"
                ],
                "portable": compatibility[
                    "portable_adoption_evidence"
                ],
                "authority": compatibility[
                    "compatibility_proof_authority"
                ],
            },
        )
    else:
        raise EvidenceFailed(f"no schema/CLI/UX executor for {slug}")
    return checks.finish(parameters)


def v2_execute_source_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    del manifest
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "source", "slug": slug}

    def capture_state(
        rows: Sequence[Mapping[str, Any]],
        *,
        lint: Mapping[str, Any] | None = None,
        tracker_status: Mapping[str, Any] | None = None,
        capabilities: Mapping[str, Any] | None = None,
        source_files: Sequence[Mapping[str, Any]] | None = None,
        rule_contract: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        ordered = sorted((dict(row) for row in rows), key=lambda row: row["id"])
        normalized_lint = (
            dict(lint)
            if lint is not None
            else fixture_lint(
                ordered,
                {
                    str(row["id"]): tuple(row.get("missing_sections") or ())
                    for row in ordered
                },
            )
        )
        return v2_capture_state(
            issue_ids=[str(row["id"]) for row in ordered],
            full_issues=ordered,
            lint=normalized_lint,
            tracker_status=dict(tracker_status or {"state": "clean"}),
            sync_status={"state": "synchronized"},
            export_witness={"state": "current"},
            version={"version": "0.2.19"},
            capabilities=dict(
                capabilities or {"contract_version": "br.capabilities.v1"}
            ),
            source_files=list(
                source_files
                or [
                    {
                        "path": "synthetic-source",
                        "bytes": 1,
                        "content_identity": text_root("x"),
                    }
                ]
            ),
            rule_contract=dict(
                rule_contract
                or {
                    "classifier": (
                        "synthetic-independent-template-findings"
                    )
                }
            ),
        )

    def authentic_capture(
        raw_rows: Sequence[Mapping[str, Any]],
        *,
        missing_by_id: Mapping[str, Sequence[str]] | None = None,
        tracker_status: Mapping[str, Any] | None = None,
        capabilities: Mapping[str, Any] | None = None,
        source_files: Sequence[Mapping[str, Any]] | None = None,
        rule_contract: Mapping[str, Any] | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any], LiveSnapshot, dict[str, Any]]:
        full_issues, lint, snapshot, inventory = (
            v2_authentic_projection_fixture(
                raw_rows,
                missing_by_id=missing_by_id,
            )
        )
        return (
            capture_state(
                full_issues,
                lint=lint,
                tracker_status=tracker_status,
                capabilities=capabilities,
                source_files=source_files,
                rule_contract=rule_contract,
            ),
            lint,
            snapshot,
            inventory,
        )

    if slug == "source-zero-one":
        empty_capture = capture_state([])
        checks.check(
            "empty-source-capture-is-first-class",
            v2_list_issue_ids([], label="empty issue list") == []
            and empty_capture["issue_ids"] == []
            and empty_capture["issue_count"] == 0
            and empty_capture["full_issue_projection_root"]
            == semantic_root([]),
            expected={
                "issue_ids": [],
                "issue_count": 0,
                "full_issue_projection_root": semantic_root([]),
            },
            observed={
                "issue_ids": empty_capture["issue_ids"],
                "issue_count": empty_capture["issue_count"],
                "full_issue_projection_root": empty_capture[
                    "full_issue_projection_root"
                ],
            },
        )
        for count in (0, 1):
            inventory = v2_synthetic_inventory(
                [v2_synthetic_target(0)] if count else []
            )
            checks.check(
                f"cardinality-{count}",
                inventory["counts"]["targets"] == count
                and len(inventory["rows"]) == count,
                expected=count,
                observed=inventory["counts"]["targets"],
            )
        no_warning_id = "fixture-no-template-warning"
        _, _, no_warning_snapshot, no_warning_inventory = authentic_capture(
            [
                fixture_issue(
                    issue_id=no_warning_id,
                    status="open",
                )
            ],
            missing_by_id={no_warning_id: ()},
        )
        no_warning_row = no_warning_snapshot.inventory["rows"][0]
        derived_no_warning = v2_derive_authority(
            no_warning_inventory,
            v2_empty_review_receipts(
                inventory_root=no_warning_inventory["semantic_root"],
                campaign_epoch_root=no_warning_inventory[
                    "campaign_epoch_root"
                ],
            ),
            current_br_version="0.2.19",
        )["decisions"][0]
        checks.check(
            "nonclosed-no-warning-still-inventoried-unreviewed",
            no_warning_snapshot.inventory["counts"][
                "complete_review_scope_issues"
            ]
            == 1
            and no_warning_snapshot.inventory["counts"][
                "no_template_warning_issues"
            ]
            == 1
            and no_warning_row["template_warning_state"] == "NONE"
            and no_warning_row["semantic_review_disposition"]
            == "BLOCKED_AUTHORITY"
            and no_warning_row["semantic_review_receipt_state"]
            == "UNREVIEWED"
            and no_warning_row["semantic_review_dimensions"]
            == v2_unreviewed_semantic_dimensions()
            and no_warning_row["semantic_review_receipt_root"] is None
            and derived_no_warning["semantic_review_action"]
            == "SEMANTIC_REVIEW_REQUIRED"
            and no_warning_inventory["rows"][0]["id"] == no_warning_id,
            expected={
                "complete_scope": 1,
                "warning_state": "NONE",
                "review_state": "UNREVIEWED",
                "disposition": "BLOCKED_AUTHORITY",
            },
            observed={
                "counts": no_warning_snapshot.inventory["counts"],
                "warning_state": no_warning_row["template_warning_state"],
                "review_state": no_warning_row[
                    "semantic_review_receipt_state"
                ],
                "disposition": no_warning_row[
                    "semantic_review_disposition"
                ],
                "semantic_action": derived_no_warning[
                    "semantic_review_action"
                ],
            },
        )
        malformed_unreviewed = dict(no_warning_inventory["rows"][0])
        malformed_unreviewed["semantic_review_dimensions"] = (
            v2_unreviewed_semantic_dimensions()[:-1]
        )
        checks.refuses(
            "partial-unreviewed-dimensions-refused",
            InputRefused,
            lambda: v2_validate_unreviewed_semantic_contract(
                malformed_unreviewed,
                label="malformed unreviewed fixture",
            ),
            contains="exact unreviewed semantic contract",
        )
        closed_id = "fixture-closed-without-finding"
        _, _, closed_snapshot, closed_inventory = authentic_capture(
            [
                fixture_issue(
                    issue_id=closed_id,
                    status="closed",
                )
            ],
            missing_by_id={closed_id: ()},
        )
        checks.check(
            "closed-no-finding-remains-outside-active-review-scope",
            closed_snapshot.inventory["rows"] == []
            and closed_inventory["rows"] == [],
            expected=0,
            observed=len(closed_inventory["rows"]),
        )
    elif slug in {
        "source-rows-9-10-11",
        "source-rows-12-13",
        "source-rows-24-25-26",
    }:
        configurations = {
            "source-rows-9-10-11": (10, (9, 10, 11)),
            "source-rows-12-13": (13, (12, 13)),
            "source-rows-24-25-26": (25, (24, 25, 26)),
        }
        cap, populations = configurations[slug]
        for population in populations:
            plan, _, _ = v2_plan_for_count(
                population,
                max_targets=cap,
            )
            expected_children = math.ceil(population / cap)
            mapped = [
                target_id
                for child in plan["children"]
                for target_id in child["target_ids"]
            ]
            checks.check(
                f"population-{population}",
                len(plan["children"]) == expected_children
                and len(mapped) == population
                and len(mapped) == len(set(mapped)),
                expected={"children": expected_children, "targets": population},
                observed={
                    "children": len(plan["children"]),
                    "targets": len(mapped),
                },
            )
    elif slug == "source-rows-4096":
        v2_validate_source_limits(
            row_count=4_096,
            warning_count=0,
            maximum_warnings_per_issue=0,
        )
        checks.check(
            "row-cap-admitted",
            True,
            expected=4_096,
            observed=4_096,
        )
        checks.refuses(
            "row-cap-plus-one",
            InputRefused,
            lambda: v2_validate_source_limits(
                row_count=4_097,
                warning_count=0,
                maximum_warnings_per_issue=0,
            ),
            contains="row count",
        )
    elif slug == "source-warnings-8192":
        v2_validate_source_limits(
            row_count=2_731,
            warning_count=8_192,
            maximum_warnings_per_issue=3,
        )
        checks.check(
            "warning-cap-admitted",
            True,
            expected=8_192,
            observed=8_192,
        )
        checks.refuses(
            "warning-cap-plus-one",
            InputRefused,
            lambda: v2_validate_source_limits(
                row_count=2_731,
                warning_count=8_193,
                maximum_warnings_per_issue=3,
            ),
            contains="warning count",
        )
    elif slug == "source-all-types-statuses-priorities":
        statuses = ["open", "in_progress", "blocked", "deferred", "closed"]
        types = ["bug", "task", "feature", "epic", "chore", "docs", "question", "custom:x"]
        rows = [
            v2_synthetic_target(
                index,
                priority=index % 5,
                status=statuses[index % len(statuses)],
                issue_type=types[index % len(types)],
            )
            for index in range(40)
        ]
        checks.check(
            "covering-array-priorities",
            {row["priority"] for row in rows} == set(range(5)),
            expected=list(range(5)),
            observed=sorted({row["priority"] for row in rows}),
        )
        checks.check(
            "covering-array-statuses-types",
            {row["status"] for row in rows} == set(statuses)
            and {row["type"] for row in rows} == set(types),
            expected={"statuses": statuses, "types": types},
            observed={
                "statuses": sorted({row["status"] for row in rows}),
                "types": sorted({row["type"] for row in rows}),
            },
        )
        raw_rows = [
            fixture_issue(
                issue_id=(
                    f"fixture-enum-{type_index:02d}-"
                    f"{status_index:02d}-{priority}"
                ),
                issue_type=issue_type,
                status=status,
                priority=priority,
            )
            for type_index, issue_type in enumerate(types)
            for status_index, status in enumerate(statuses)
            for priority in range(5)
        ]
        full_issues, _, _, authentic_inventory = (
            v2_authentic_projection_fixture(raw_rows)
        )
        expected_product = {
            (issue_type, status, priority)
            for issue_type in types
            for status in statuses
            for priority in range(5)
        }
        observed_product = {
            (row["type"], row["status"], row["priority"])
            for row in full_issues
        }
        expected_selected_product = {
            coordinate
            for coordinate in expected_product
            if coordinate[1] != "closed"
            or fixture_expected_missing(coordinate[0])
        }
        observed_selected_product = {
            (row["type"], row["status"], row["priority"])
            for row in authentic_inventory["rows"]
        }
        checks.check(
            "raw-source-cartesian-enum-coverage",
            len(full_issues) == len(types) * len(statuses) * 5
            and observed_product == expected_product
            and observed_selected_product == expected_selected_product
            and len({row["id"] for row in full_issues}) == len(full_issues)
            and authentic_inventory["counts"]["targets"]
            == len(authentic_inventory["rows"]),
            expected={
                "rows": len(types) * len(statuses) * 5,
                "cartesian_root": semantic_root(
                    sorted(expected_product)
                ),
                "selected_cartesian_root": semantic_root(
                    sorted(expected_selected_product)
                ),
            },
            observed={
                "rows": len(full_issues),
                "cartesian_root": semantic_root(
                    sorted(observed_product)
                ),
                "selected_cartesian_root": semantic_root(
                    sorted(observed_selected_product)
                ),
            },
        )
        nullable_collections = fixture_issue(
            issue_id="fixture-null-collections"
        )
        nullable_collections["labels"] = None
        nullable_collections["dependencies"] = None
        nullable_collections["dependents"] = None
        nullable_projection = v2_full_issue_projection(
            nullable_collections
        )
        checks.check(
            "missing-null-collections-normalize-empty",
            nullable_projection["labels"] == []
            and nullable_projection["dependencies"] == []
            and nullable_projection["dependents"] == [],
            expected={"labels": [], "dependencies": [], "dependents": []},
            observed={
                "labels": nullable_projection["labels"],
                "dependencies": nullable_projection["dependencies"],
                "dependents": nullable_projection["dependents"],
            },
        )
        for field in ("labels", "dependencies", "dependents"):
            for index, malformed in enumerate((False, 0, "")):
                candidate = fixture_issue(
                    issue_id=f"fixture-falsey-{field}-{index}"
                )
                candidate[field] = malformed
                checks.refuses(
                    f"{field}-falsey-{index}-refused",
                    InfrastructureFailed,
                    lambda candidate=candidate: v2_full_issue_projection(
                        candidate
                    ),
                    contains=f"invalid {field}",
                )
        malformed_relations = (
            {"id": "", "type": "blocks"},
            {"id": "other", "type": ""},
            {"id": "other", "type": False},
            {"id": "other", "type": "blocks", "status": ""},
            {"id": "other", "type": "blocks", "priority": True},
            {"id": "other", "type": "blocks", "priority": 5},
        )
        for index, relation in enumerate(malformed_relations):
            candidate = fixture_issue(
                issue_id=f"fixture-malformed-relation-{index}",
                dependencies=(relation,),
            )
            checks.refuses(
                f"relation-row-{index}-refused",
                InfrastructureFailed,
                lambda candidate=candidate: v2_full_issue_projection(
                    candidate
                ),
                contains="invalid relation row",
            )
    elif slug == "source-warning-partitions":
        sections = (
            "## Acceptance Criteria",
            "## Steps to Reproduce",
            "## Success Criteria",
        )
        combinations = (
            (sections[0],),
            (sections[1],),
            (sections[2],),
            (sections[0], sections[1]),
            (sections[0], sections[2]),
            (sections[1], sections[2]),
            sections,
        )
        issues = [
            fixture_issue(
                issue_id=f"fixture-v2-overlap-{index}",
                issue_type="bug",
                status=STATUS_SCOPES[index % len(STATUS_SCOPES)],
                priority=index % 5,
            )
            for index in range(len(combinations))
        ]
        issues.append(
            fixture_issue(
                issue_id="fixture-v2-no-warning",
                issue_type="chore",
                status="open",
                priority=4,
            )
        )
        missing = {
            issue["id"]: combination
            for issue, combination in zip(
                issues[: len(combinations)],
                combinations,
                strict=True,
            )
        }
        _, lint, snapshot, inventory = (
            v2_authentic_projection_fixture(
                issues,
                missing_by_id=missing,
            )
        )
        expected_memberships = {
            "A_only": ["fixture-v2-overlap-0"],
            "S_only": ["fixture-v2-overlap-1"],
            "C_only": ["fixture-v2-overlap-2"],
            "A_and_S_only": ["fixture-v2-overlap-3"],
            "A_and_C_only": ["fixture-v2-overlap-4"],
            "S_and_C_only": ["fixture-v2-overlap-5"],
            "A_and_S_and_C": ["fixture-v2-overlap-6"],
            "NO_TEMPLATE_WARNING": ["fixture-v2-no-warning"],
        }
        observed_memberships = {
            name: row["issue_ids"]
            for name, row in snapshot.inventory["partitions"].items()
        }
        checks.check(
            "seven-exclusive-warning-partitions",
            observed_memberships == expected_memberships
            and sum(
                row["issues"]
                for row in snapshot.inventory["partitions"].values()
            )
            == 8
            and sum(
                row["warnings"]
                for row in snapshot.inventory["partitions"].values()
            )
            == 12
            and snapshot.inventory["counts"][
                "template_warning_issues"
            ]
            == 7
            and snapshot.inventory["counts"][
                "no_template_warning_issues"
            ]
            == 1,
            expected={
                "memberships": expected_memberships,
                "issues": 8,
                "warnings": 12,
                "warning_issues": 7,
                "no_warning_issues": 1,
            },
            observed={
                "memberships": observed_memberships,
                "issues": sum(
                    row["issues"]
                    for row in snapshot.inventory["partitions"].values()
                ),
                "warnings": sum(
                    row["warnings"]
                    for row in snapshot.inventory["partitions"].values()
                ),
                "warning_issues": snapshot.inventory["counts"][
                    "template_warning_issues"
                ],
                "no_warning_issues": snapshot.inventory["counts"][
                    "no_template_warning_issues"
                ],
            },
        )
        reversed_snapshot = v2_authentic_projection_fixture(
            list(reversed(issues)),
            missing_by_id=dict(reversed(list(missing.items()))),
        )[2]
        checks.check(
            "warning-partitions-input-order-invariant",
            reversed_snapshot.inventory["semantic_root"]
            == snapshot.inventory["semantic_root"],
            expected=snapshot.inventory["semantic_root"],
            observed=reversed_snapshot.inventory["semantic_root"],
        )
        zero_sets = v2_build_zero_sets(
            source_root=semantic_root({"fixture": "warning-partitions"}),
            inventory=inventory,
            prior_campaign=v2_empty_prior_campaign(),
            current_universe=issues,
        )
        checks.check(
            "production-zero-cells-rooted",
            zero_sets["counts"]["cells"] == 25
            and zero_sets["counts"]["issues"] == 8
            and all(
                cell["zero_receipt"] is None
                or (
                    cell["zero_receipt"]["count"] == 0
                    and cell["zero_receipt"]["semantic_root"]
                    == semantic_root(
                        {
                            key: value
                            for key, value in cell[
                                "zero_receipt"
                            ].items()
                            if key != "semantic_root"
                        }
                    )
                )
                for cell in zero_sets["cells"]
            ),
            expected={"cells": 25, "issues": 8, "receipts": "rooted"},
            observed=zero_sets["counts"],
        )
        duplicate_lint = json.loads(canonical_bytes(lint))
        duplicate = dict(duplicate_lint["all"]["results"][0])
        duplicate_lint["all"]["results"].append(duplicate)
        duplicate_lint["all"]["issues"] += 1
        duplicate_lint["all"]["total"] += duplicate["warnings"]
        checks.refuses(
            "hidden-duplicate-warning-row-refused",
            EvidenceFailed,
            lambda: assemble_inventory(
                duplicate_lint,
                issues,
                fixture_source(issues),
                include_issue_rows_without_findings=True,
            ),
            contains="duplicate issue",
        )
    elif slug == "source-double-capture-coherent":
        raw_rows = [
            fixture_issue(
                issue_id="fixture-capture-open",
                priority=0,
                status="open",
            ),
            fixture_issue(
                issue_id="fixture-capture-closed",
                priority=4,
                status="closed",
            ),
        ]
        first, _, first_snapshot, first_inventory = authentic_capture(raw_rows)
        second, _, second_snapshot, second_inventory = authentic_capture(
            list(reversed(raw_rows))
        )
        coherent_root = v2_validate_capture_pair(first, second)
        checks.check(
            "production-coherence-validator-admits-equal-observations",
            coherent_root == first["semantic_root"] == second["semantic_root"]
            and first_snapshot.inventory["semantic_root"]
            == second_snapshot.inventory["semantic_root"]
            and first_inventory["semantic_root"]
            == second_inventory["semantic_root"],
            expected=first["semantic_root"],
            observed=coherent_root,
        )
        checks.check(
            "capture-binds-all-source-dimensions",
            set(first) == V2_CAPTURE_STATE_KEYS,
            expected=sorted(V2_CAPTURE_STATE_KEYS),
            observed=sorted(first),
        )
    elif slug == "source-within-run-drift":
        baseline_rows = [
            fixture_issue(
                issue_id="fixture-drift-a",
                priority=1,
                status="open",
                owner="owner-a",
                dependencies=(
                    {
                        "id": "fixture-neighbor-a",
                        "dependency_type": "blocks",
                        "status": "open",
                        "priority": 2,
                    },
                ),
            ),
            fixture_issue(
                issue_id="fixture-drift-b",
                priority=2,
                status="blocked",
                owner="owner-b",
            ),
        ]
        baseline, baseline_lint, _, _ = authentic_capture(baseline_rows)
        mutations: list[tuple[str, dict[str, Any]]] = []
        for dimension, field, value in (
            ("field", "title", "changed title"),
            (
                "relation",
                "dependencies",
                [
                    {
                        "id": "fixture-neighbor-b",
                        "dependency_type": "blocks",
                        "status": "open",
                        "priority": 3,
                    }
                ],
            ),
            ("status", "status", "closed"),
            ("priority", "priority", 3),
            ("owner", "owner", "changed-owner"),
            ("assignee", "assignee", "changed-assignee"),
        ):
            changed_rows = json.loads(json.dumps(baseline_rows))
            changed_rows[0][field] = value
            changed, _, _, _ = authentic_capture(changed_rows)
            mutations.append((dimension, changed))
        membership_rows = [
            baseline_rows[0],
            fixture_issue(
                issue_id="fixture-drift-c",
                priority=2,
                status="blocked",
            ),
        ]
        membership_changed, _, _, _ = authentic_capture(membership_rows)
        warning_membership = {
            "fixture-drift-a": ("## Acceptance Criteria",),
            "fixture-drift-b": (
                "## Acceptance Criteria",
                "## Steps to Reproduce",
            ),
        }
        lint_changed, _, _, _ = authentic_capture(
            baseline_rows,
            missing_by_id=warning_membership,
        )
        mutations.extend(
            [
                ("selected-membership", membership_changed),
                (
                    "tracker-status",
                    authentic_capture(
                        baseline_rows,
                        tracker_status={"state": "dirty"},
                    )[0],
                ),
                (
                    "capability",
                    authentic_capture(
                        baseline_rows,
                        capabilities={
                            "contract_version": "br.capabilities.v2"
                        },
                    )[0],
                ),
                ("lint-status-cut", lint_changed),
                (
                    "source-file",
                    authentic_capture(
                        baseline_rows,
                        source_files=[
                            {
                                "path": "synthetic-source",
                                "bytes": 1,
                                "content_identity": text_root("changed"),
                            }
                        ],
                    )[0],
                ),
                (
                    "rule-contract",
                    authentic_capture(
                        baseline_rows,
                        rule_contract={"classifier": "changed-rule"},
                    )[0],
                ),
            ]
        )
        for dimension, changed in mutations:
            checks.refuses(
                f"drift-{dimension}",
                InputRefused,
                lambda changed=changed: v2_validate_capture_pair(
                    baseline,
                    changed,
                ),
                contains="ConcurrentDrift",
            )
    elif slug == "source-count-preserving-swap":
        first_rows = [
            fixture_issue(
                issue_id="fixture-swap-a",
                title="First authentic raw tracker row",
            ),
            fixture_issue(
                issue_id="fixture-swap-b",
                title="Second authentic raw tracker row",
            ),
        ]
        first_missing = {
            "fixture-swap-a": ("## Acceptance Criteria",),
            "fixture-swap-b": ("## Steps to Reproduce",),
        }
        first, _, _, _ = authentic_capture(
            first_rows,
            missing_by_id=first_missing,
        )
        field_swap = json.loads(json.dumps(first_rows))
        field_swap[0]["title"], field_swap[1]["title"] = (
            field_swap[1]["title"],
            field_swap[0]["title"],
        )
        membership_swap = [
            first_rows[0],
            fixture_issue(
                issue_id="fixture-swap-c",
                title="Replacement authentic raw tracker row",
            ),
        ]
        lint_swap, _, _, _ = authentic_capture(
            first_rows,
            missing_by_id={
                "fixture-swap-a": ("## Steps to Reproduce",),
                "fixture-swap-b": ("## Acceptance Criteria",),
            },
        )
        field_swap_capture, _, _, _ = authentic_capture(
            field_swap,
            missing_by_id=first_missing,
        )
        membership_capture, _, _, _ = authentic_capture(
            membership_swap,
            missing_by_id={
                "fixture-swap-a": ("## Acceptance Criteria",),
                "fixture-swap-c": ("## Steps to Reproduce",),
            },
        )
        for name, changed in (
            ("field-swap", field_swap_capture),
            ("drop-add", membership_capture),
            ("warning-swap", lint_swap),
        ):
            checks.refuses(
                f"equal-count-{name}",
                InputRefused,
                lambda changed=changed: v2_validate_capture_pair(first, changed),
                contains="ConcurrentDrift",
            )
        duplicate_rows = [first_rows[0], first_rows[0]]
        checks.refuses(
            "duplicate-membership",
            InputRefused,
            lambda: authentic_capture(duplicate_rows),
            contains="duplicate",
        )
    elif slug == "source-cross-run-drift-scope":
        selected_raw = fixture_issue(
            issue_id="fixture-selected",
            title="Selected authentic tracker target",
            priority=1,
            status="open",
            owner="selected-owner",
            dependencies=(
                {
                    "id": "fixture-selected-neighbor",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 2,
                },
            ),
        )
        unrelated_a = fixture_issue(
            issue_id="fixture-unrelated",
            title="Unrelated authentic tracker target",
            priority=3,
            status="blocked",
        )
        unrelated_b = dict(unrelated_a)
        unrelated_b["description"] = (
            "Unrelated changed source clause that must move only the whole "
            "observation and campaign roots."
        )

        def planned_fixture(
            raw_rows: Sequence[Mapping[str, Any]],
            *,
            missing_by_id: Mapping[str, Sequence[str]] | None = None,
        ) -> tuple[
            dict[str, Any],
            dict[str, Any],
            dict[str, Any],
            dict[str, Any],
        ]:
            state, _, _, inventory = authentic_capture(
                raw_rows,
                missing_by_id=missing_by_id,
            )
            receipts = v2_empty_review_receipts(
                inventory_root=inventory["semantic_root"],
                campaign_epoch_root=inventory["campaign_epoch_root"],
            )
            authority = v2_derive_authority(
                inventory,
                receipts,
                current_br_version="0.2.19",
            )
            plan, _ = v2_build_review_plan(
                inventory,
                authority,
                max_targets=1,
            )
            return state, inventory, authority, plan

        def child_key_for(
            plan: Mapping[str, Any],
            target_id: str,
        ) -> str:
            matches = [
                child["child_key"]
                for child in plan["children"]
                if target_id in child["target_ids"]
            ]
            if len(matches) != 1:
                raise EvidenceFailed(
                    f"authentic fixture does not map {target_id} exactly once"
                )
            return str(matches[0])

        first_capture, first_inventory, first_authority, first_plan = (
            planned_fixture([selected_raw, unrelated_a])
        )
        second_capture, second_inventory, second_authority, second_plan = (
            planned_fixture([selected_raw, unrelated_b])
        )
        first_selected_key = child_key_for(first_plan, "fixture-selected")
        second_selected_key = child_key_for(second_plan, "fixture-selected")
        first_selected_target = next(
            row
            for row in first_inventory["rows"]
            if row["id"] == "fixture-selected"
        )
        second_selected_target = next(
            row
            for row in second_inventory["rows"]
            if row["id"] == "fixture-selected"
        )
        first_selected_decision = next(
            row
            for row in first_authority["decisions"]
            if row["target_id"] == "fixture-selected"
        )
        second_selected_decision = next(
            row
            for row in second_authority["decisions"]
            if row["target_id"] == "fixture-selected"
        )
        checks.check(
            "unrelated-drift-changes-observation-and-campaign",
            first_capture["semantic_root"] != second_capture["semantic_root"]
            and first_inventory["campaign_epoch_root"]
            != second_inventory["campaign_epoch_root"],
            expected="different observation and campaign roots",
            observed={
                "capture_before": first_capture["semantic_root"],
                "capture_after": second_capture["semantic_root"],
                "campaign_before": first_inventory["campaign_epoch_root"],
                "campaign_after": second_inventory["campaign_epoch_root"],
            },
        )
        checks.check(
            "unrelated-drift-preserves-selected-target-root",
            first_selected_target["target_root"]
            == second_selected_target["target_root"],
            expected=first_selected_target["target_root"],
            observed=second_selected_target["target_root"],
        )
        checks.check(
            "unrelated-drift-preserves-selected-decision-root",
            first_selected_decision["semantic_root"]
            == second_selected_decision["semantic_root"],
            expected=first_selected_decision["semantic_root"],
            observed=second_selected_decision["semantic_root"],
        )
        checks.check(
            "unrelated-drift-stable-selected-key",
            first_selected_key == second_selected_key,
            expected=first_selected_key,
            observed=second_selected_key,
        )

        selected_mutations: list[
            tuple[
                str,
                list[dict[str, Any]],
                Mapping[str, Sequence[str]] | None,
            ]
        ] = []
        for name, field, value in (
            ("field", "description", "Changed selected source clause."),
            ("owner", "owner", "changed-selected-owner"),
            ("priority-lane", "priority", 2),
            ("status-lane", "status", "blocked"),
            (
                "dependency-neighbor",
                "dependencies",
                [
                    {
                        "id": "fixture-changed-neighbor",
                        "dependency_type": "blocks",
                        "status": "blocked",
                        "priority": 3,
                    }
                ],
            ),
        ):
            changed_selected = json.loads(json.dumps(selected_raw))
            changed_selected[field] = value
            selected_mutations.append(
                (name, [changed_selected, dict(unrelated_a)], None)
            )
        selected_mutations.append(
            (
                "lint-membership",
                [dict(selected_raw), dict(unrelated_a)],
                {
                    "fixture-selected": ("## Steps to Reproduce",),
                    "fixture-unrelated": ("## Acceptance Criteria",),
                },
            )
        )
        for name, raw_rows, missing in selected_mutations:
            _, changed_inventory, _, changed_plan = planned_fixture(
                raw_rows,
                missing_by_id=missing,
            )
            changed_key = child_key_for(changed_plan, "fixture-selected")
            checks.check(
                f"selected-{name}-invalidates-affected-key",
                changed_key != first_selected_key
                and next(
                    row
                    for row in changed_inventory["rows"]
                    if row["id"] == "fixture-selected"
                )["target_root"]
                != next(
                    row
                    for row in first_inventory["rows"]
                    if row["id"] == "fixture-selected"
                )["target_root"],
                expected="different selected key",
                observed={
                    "before": first_selected_key,
                    "after": changed_key,
                },
            )

        _, _, _, receipt_inventory = authentic_capture([selected_raw])
        inventory = receipt_inventory
        base_receipts = v2_synthetic_receipts(
            inventory,
            declared=True,
        )
        base_authority = v2_derive_authority(
            inventory,
            base_receipts,
            current_br_version="0.2.19",
        )
        base_plan, _ = v2_build_review_plan(
            inventory,
            base_authority,
            max_targets=1,
        )
        base_child_key = base_plan["children"][0]["child_key"]
        for name, field, value in (
            ("owner", "implementation_owner", "changed-owner"),
            ("consumer", "terminal_consumer", "changed-consumer"),
        ):
            changed_receipts = json.loads(json.dumps(base_receipts))
            changed_receipt = changed_receipts["receipts"][0]
            changed_receipt[field] = value
            changed_receipt.pop("semantic_root", None)
            changed_receipts["receipts"][0] = v2_rooted(changed_receipt)
            changed_receipts.pop("semantic_root", None)
            changed_receipts = v2_rooted(changed_receipts)
            changed_authority = v2_derive_authority(
                inventory,
                changed_receipts,
                current_br_version="0.2.19",
            )
            changed_plan, _ = v2_build_review_plan(
                inventory,
                changed_authority,
                max_targets=1,
            )
            changed_child_key = changed_plan["children"][0]["child_key"]
            checks.check(
                f"selected-{name}-receipt-invalidates-child-key",
                changed_child_key != base_child_key,
                expected="different child key",
                observed={
                    "before": base_child_key,
                    "after": changed_child_key,
                },
            )
    else:
        raise EvidenceFailed(f"no source executor for {slug}")
    return checks.finish(parameters)


def v2_execute_authority_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "row-authority", "slug": slug}
    base_inventory = v2_synthetic_inventory([v2_synthetic_target(0)])
    if slug == "row-complete-planned-child":
        authority = v2_synthetic_authority(base_inventory)
        plan, _ = v2_build_review_plan(
            base_inventory,
            authority,
            max_targets=10,
        )
        child = plan["children"][0]
        required = set(
            manifest["row_contract"]["planned_child_required_fields"]
        )
        checks.check(
            "planned-child-required-fields",
            set(child) == required == V2_PLANNED_CHILD_FIELDS,
            expected=sorted(required),
            observed=sorted(child),
        )
        normalized = authority["normalized_rows"][0]
        expected_row_fields = set(
            manifest["row_contract"]["required_fields"]
        )
        checks.check(
            "normalized-authority-row-lossless",
            set(normalized)
            == expected_row_fields
            == V2_NORMALIZED_ROW_FIELDS,
            expected=sorted(expected_row_fields),
            observed=sorted(normalized),
        )
        v2_validate_child_payload(child)
        checks.check(
            "planned-child-transport-valid",
            True,
            expected="valid",
            observed=child["semantic_root"],
        )
        for field in (
            "title",
            "target_ids",
            "intended_generated_edges",
            "semantic_review_disposition",
            "semantic_review_receipt_state",
            "semantic_review_action",
            "semantic_review_receipt_roots",
            "reviewed_no_change_receipt_roots",
        ):
            mutated = dict(child)
            mutated.pop(field)
            mutated = v2_rooted(mutated)
            checks.refuses(
                f"missing-{field}",
                InputRefused,
                lambda mutated=mutated: v2_validate_child_payload(mutated),
                contains="non-closed schema",
            )

        dispositions = list(V2_SEMANTIC_REVIEW_DISPOSITIONS)
        mixed_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    index,
                    issue_id=f"semantic-{index:02d}",
                )
                for index in range(len(dispositions))
            ]
        )
        mixed_receipts = v2_synthetic_receipts(
            mixed_inventory,
            semantic_reviewed=True,
        )
        mixed_receipts = dict(mixed_receipts)
        mixed_receipts.pop("semantic_root", None)
        mixed_rows: list[dict[str, Any]] = []
        for receipt, disposition in zip(
            mixed_receipts["receipts"],
            dispositions,
            strict=True,
        ):
            updated = dict(receipt)
            updated.pop("semantic_root", None)
            updated["semantic_review_disposition"] = disposition
            signal = V2_SEMANTIC_SIGNAL_BY_DISPOSITION[disposition]
            updated["semantic_review_dimensions"] = [
                v2_semantic_dimension_receipt(
                    target_root=updated["target_root"],
                    dimension=dimension,
                    verdict=signal if index == 0 else "SATISFIED",
                    reason=f"mixed reviewed reason for {dimension}",
                    falsifier=f"mixed reviewed falsifier for {dimension}",
                )
                for index, dimension in enumerate(
                    V2_SEMANTIC_REVIEW_DIMENSIONS
                )
            ]
            if disposition == "BLOCKED_AUTHORITY":
                updated["declared_acceptance_owner"] = ""
            mixed_rows.append(v2_rooted(updated))
        mixed_receipts["receipts"] = mixed_rows
        mixed_receipts = v2_rooted(mixed_receipts)
        mixed_authority = v2_derive_authority(
            mixed_inventory,
            mixed_receipts,
            current_br_version="0.2.19",
        )
        mixed_plan, _ = v2_build_review_plan(
            mixed_inventory,
            mixed_authority,
            max_targets=10,
        )
        scheduled_ids = sorted(
            target_id
            for child_row in mixed_plan["children"]
            for target_id in child_row["target_ids"]
        )
        retained_ids = sorted(
            row["target_id"]
            for row in mixed_plan["retained_without_direct_child"]
        )
        action_by_disposition = {
            row["semantic_review_disposition"]: row[
                "semantic_review_action"
            ]
            for row in mixed_authority["decisions"]
        }
        checks.check(
            "semantic-plan-exact-scheduled-retained-partition",
            action_by_disposition
            == {
                "REMEDIATION_REQUIRED": "REMEDIATION_CANDIDATE",
                "REVIEWED_NO_CHANGE": "RETAINED_ADJUDICATION",
                "ROLLUP_ONLY": "RETAINED_ADJUDICATION",
                "CONTRIBUTION_ONLY": "RETAINED_ADJUDICATION",
                "BLOCKED_AUTHORITY": "AUTHORITY_RESOLUTION_REQUIRED",
                "TYPED_INAPPLICABLE": "RETAINED_ADJUDICATION",
            }
            and len(mixed_plan["semantic_adjudications"]) == 6
            and len(mixed_plan["remediation_candidates"]) == 1
            and len(scheduled_ids) == 2
            and len(retained_ids) == 4
            and sorted([*scheduled_ids, *retained_ids])
            == sorted(row["id"] for row in mixed_inventory["rows"])
            and all(
                set(row) == V2_NORMALIZED_ROW_FIELDS
                for row in mixed_authority["normalized_rows"]
            ),
            expected={
                "adjudications": 6,
                "scheduled": 2,
                "retained": 4,
                "remediation": 1,
            },
            observed={
                "adjudications": len(
                    mixed_plan["semantic_adjudications"]
                ),
                "scheduled": len(scheduled_ids),
                "retained": len(retained_ids),
                "remediation": len(
                    mixed_plan["remediation_candidates"]
                ),
                "actions": action_by_disposition,
            },
        )
    elif slug == "row-dispositions-distinct":
        dispositions = [
            "MALFORMED_OR_WRONG_TYPE",
            "ROLLUP_CHILD_SET_GAP",
            "OWNER_REVIEW_REQUIRED",
            "SUBSTANTIVE_SEMANTIC_OMISSION",
            "SECTION_NAME_ONLY",
            "HISTORICAL_IMMUTABLE_REVIEW",
        ]
        roots: list[str] = []
        for index, disposition in enumerate(dispositions):
            inventory = v2_synthetic_inventory(
                [
                    v2_synthetic_target(
                        index,
                        disposition=disposition,
                        status="closed"
                        if disposition == "HISTORICAL_IMMUTABLE_REVIEW"
                        else "open",
                    )
                ]
            )
            authority = v2_synthetic_authority(inventory)
            if disposition == "HISTORICAL_IMMUTABLE_REVIEW":
                description, acceptance, design, notes = v2_child_text(
                    inventory["rows"],
                    authority["decisions"],
                    oversize=False,
                )
                roots.append(
                    semantic_root([description, acceptance, design, notes])
                )
            else:
                plan, _ = v2_build_review_plan(
                    inventory,
                    authority,
                    max_targets=10,
                )
                roots.append(plan["children"][0]["description_root"])
        checks.check(
            "disposition-workflows-distinct",
            len(set(roots)) == len(dispositions),
            expected=len(dispositions),
            observed=len(set(roots)),
        )
    elif slug == "authority-candidate-provenance":
        issue = {
            "authority_domain": "domain:solver",
            "parent": "parent-1",
            "labels": ["crate:fs-la", "unrelated"],
            "mapping": {"paths": ["crates/fs-la/src/lib.rs"]},
        }
        candidates = v2_domain_candidates(issue)
        checks.check(
            "candidate-sources-rooted",
            len(candidates) == 4
            and all(
                candidate["provenance_root"].startswith("sha256-v1:")
                and candidate["falsifier"]
                for candidate in candidates
            ),
            expected=4,
            observed=candidates,
        )
        authority = v2_synthetic_authority(base_inventory)
        checks.check(
            "candidates-do-not-promote",
            authority["decisions"][0]["readiness"] == "REVIEW_ONLY",
            expected="REVIEW_ONLY",
            observed=authority["decisions"][0]["readiness"],
        )
    elif slug == "authority-self-report-declared":
        authority = v2_synthetic_authority(
            base_inventory,
            declared=True,
        )
        decision = authority["decisions"][0]
        checks.check(
            "self-report-ceiling",
            decision["readiness"] == "DECLARED_READY"
            and decision["remediation_route"] == "ANALYSIS_ONLY",
            expected=("DECLARED_READY", "ANALYSIS_ONLY"),
            observed=(decision["readiness"], decision["remediation_route"]),
        )
    elif slug == "authority-external-receipt":
        for verdict in (
            "NODATA",
            "INVALID",
            "EXPIRED",
            "REVOKED",
            "CONFLICTED",
        ):
            authority = v2_synthetic_authority(
                base_inventory,
                external_verdict=verdict,
            )
            checks.check(
                f"external-{verdict.lower()}-not-verified",
                authority["decisions"][0]["external_authority"]["verified"]
                is False,
                expected=False,
                observed=authority["decisions"][0]["external_authority"][
                    "verified"
                ],
            )
        valid = v2_synthetic_authority(
            base_inventory,
            declared=True,
            external_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=True,
        )
        checks.check(
            "independent-fixture-external-valid",
            valid["decisions"][0]["external_authority"]["verified"] is True
            and valid["decisions"][0]["readiness"] == "DECLARED_READY",
            expected=(True, "DECLARED_READY"),
            observed=(
                valid["decisions"][0]["external_authority"]["verified"],
                valid["decisions"][0]["readiness"],
            ),
        )
    elif slug == "capability-valid-missing-failed":
        for verdict in ("NODATA", "FAILED"):
            authority = v2_synthetic_authority(
                base_inventory,
                conditional_verdict=verdict,
            )
            checks.check(
                f"capability-{verdict.lower()}-false",
                authority["decisions"][0]["conditional_write_capability"][
                    "verified"
                ]
                is False,
                expected=False,
                observed=authority["decisions"][0][
                    "conditional_write_capability"
                ]["verified"],
            )
        valid_only = v2_synthetic_authority(
            base_inventory,
            conditional_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=True,
        )
        checks.check(
            "capability-alone-not-mechanical",
            valid_only["decisions"][0]["readiness"] != "MECHANICALLY_APPLY_ELIGIBLE",
            expected="not mechanical",
            observed=valid_only["decisions"][0]["readiness"],
        )
    elif slug == "capability-lying-nonatomic-version":
        for verdict in (
            "LYING",
            "NON_ATOMIC",
            "VERSION_MISMATCHED",
            "CONFLICTED",
            "FAILED",
        ):
            authority = v2_synthetic_authority(
                base_inventory,
                conditional_verdict=verdict,
                version="0.3.0",
                allow_mechanical_fixture=True,
            )
            checks.check(
                f"{verdict.lower()}-not-conditional",
                authority["decisions"][0]["conditional_write_capability"][
                    "verified"
                ]
                is False,
                expected=False,
                observed=authority["decisions"][0][
                    "conditional_write_capability"
                ]["verified"],
            )
    elif slug == "readiness-two-gate-truth-table":
        observed: dict[str, str] = {}
        for external in ("NODATA", "VALID"):
            for conditional in ("NODATA", "VALID"):
                for gate in ("NODATA", "VALID"):
                    key = f"{external}/{conditional}/{gate}"
                    authority = v2_synthetic_authority(
                        base_inventory,
                        declared=True,
                        external_verdict=external,
                        conditional_verdict=conditional,
                        gate_verdict=gate,
                        version="0.3.0",
                        allow_mechanical_fixture=True,
                    )
                    observed[key] = authority["decisions"][0]["readiness"]
        checks.check(
            "both-gates-plus-admission-only",
            observed["VALID/VALID/VALID"]
            == "MECHANICALLY_APPLY_ELIGIBLE"
            and all(
                value != "MECHANICALLY_APPLY_ELIGIBLE"
                for key, value in observed.items()
                if key != "VALID/VALID/VALID"
            ),
            expected="only VALID/VALID/VALID mechanical",
            observed=observed,
        )
        current = v2_synthetic_authority(
            base_inventory,
            declared=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.2.19",
            allow_mechanical_fixture=True,
        )
        checks.check(
            "current-tool-nodata",
            current["decisions"][0]["readiness"] == "DECLARED_READY"
            and current["current_br_conditional_write_capability"]
            == "AUTOMATION_NODATA",
            expected=("DECLARED_READY", "AUTOMATION_NODATA"),
            observed=(
                current["decisions"][0]["readiness"],
                current["current_br_conditional_write_capability"],
            ),
        )
    elif slug == "route-manual-distinct":
        manual = v2_synthetic_authority(
            base_inventory,
            declared=True,
            manual=True,
        )["decisions"][0]
        automated = v2_synthetic_authority(
            base_inventory,
            declared=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=True,
        )["decisions"][0]
        analysis = v2_synthetic_authority(base_inventory)["decisions"][0]
        checks.check(
            "three-routes-distinct",
            {
                analysis["remediation_route"],
                manual["remediation_route"],
                automated["remediation_route"],
            }
            == set(V2_REMEDIATION_ROUTES),
            expected=sorted(V2_REMEDIATION_ROUTES),
            observed=sorted(
                {
                    analysis["remediation_route"],
                    manual["remediation_route"],
                    automated["remediation_route"],
                }
            ),
        )
        checks.check(
            "manual-no-cas-claims",
            manual["manual_authorization"]["mechanical_authority"] is False
            and manual["manual_authorization"][
                "no_cas_no_clobber_no_exactly_once"
            ]
            is True,
            expected=True,
            observed=manual["manual_authorization"],
        )
    elif slug == "route-deferred-reactivation":
        deferred_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0, status="deferred")]
        )
        authority = v2_synthetic_authority(
            deferred_inventory,
            declared=True,
            manual=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=True,
        )
        decision = authority["decisions"][0]
        checks.check(
            "deferred-always-analysis",
            decision["remediation_route"] == "ANALYSIS_ONLY"
            and decision["deferred_apply_prohibition"] is True,
            expected=("ANALYSIS_ONLY", True),
            observed=(
                decision["remediation_route"],
                decision["deferred_apply_prohibition"],
            ),
        )
    elif slug == "route-active-owner-conflict":
        for status, assignee in (("in_progress", ""), ("open", "agent")):
            inventory = v2_synthetic_inventory(
                [v2_synthetic_target(0, status=status, assignee=assignee)]
            )
            authority = v2_synthetic_authority(
                inventory,
                declared=True,
                manual=True,
            )
            plan, _ = v2_build_review_plan(
                inventory,
                authority,
                max_targets=10,
            )
            checks.check(
                f"active-{status}-{bool(assignee)}",
                authority["decisions"][0]["remediation_route"] == "ANALYSIS_ONLY"
                and plan["children"][0]["desired_status"] == "deferred",
                expected=("ANALYSIS_ONLY", "deferred"),
                observed=(
                    authority["decisions"][0]["remediation_route"],
                    plan["children"][0]["desired_status"],
                ),
            )
    elif slug == "route-no-target-mutation":
        before = semantic_root(base_inventory["rows"])
        authority = v2_synthetic_authority(
            base_inventory,
            declared=True,
            manual=True,
        )
        v2_build_review_plan(base_inventory, authority, max_targets=10)
        after = semantic_root(base_inventory["rows"])
        checks.check(
            "planning-target-unchanged",
            before == after,
            expected=before,
            observed=after,
        )
    else:
        raise EvidenceFailed(f"no authority executor for {slug}")
    return checks.finish(parameters)


def v2_execute_packing_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    del manifest
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "packing", "slug": slug}
    if slug == "packing-hard-keys":
        base = v2_synthetic_target(0)
        authority = v2_synthetic_authority(
            v2_synthetic_inventory([base])
        )["decisions"][0]
        base_vector = v2_hard_vector(base, authority)
        mutations = {
            "priority": {"priority": 3},
            "status": {"status": "blocked"},
            "disposition": {"disposition": "OWNER_REVIEW_REQUIRED"},
            "type": {"type": "bug"},
            "missing": {"missing_sections": ["## Success Criteria"]},
        }
        for name, changes in mutations.items():
            target = dict(base)
            target.update(changes)
            checks.check(
                f"hard-key-{name}",
                v2_hard_vector(target, authority) != base_vector,
                expected="different vector",
                observed=v2_hard_vector(target, authority),
            )
        changed_authority = dict(authority)
        changed_authority["semantic_review_disposition"] = (
            "BLOCKED_AUTHORITY"
        )
        checks.check(
            "hard-key-semantic-review-disposition",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["semantic_review_receipt_state"] = (
            "ROOT_BOUND_REVIEWED"
        )
        checks.check(
            "hard-key-semantic-review-receipt-state",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["semantic_review_action"] = (
            "AUTHORITY_RESOLUTION_REQUIRED"
        )
        checks.check(
            "hard-key-semantic-review-action",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["readiness"] = "DECLARED_READY"
        checks.check(
            "hard-key-readiness",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["remediation_route"] = "MANUAL_BR_REVIEW"
        checks.check(
            "hard-key-remediation-route",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
    elif slug == "packing-compatible-receipt":
        plan, _, _ = v2_plan_for_count(2, max_targets=10)
        checks.check(
            "compatible-merge",
            len(plan["children"]) == 1
            and len(plan["children"][0]["target_ids"]) == 2,
            expected={"children": 1, "targets": 2},
            observed={
                "children": len(plan["children"]),
                "targets": len(plan["children"][0]["target_ids"]),
            },
        )
        checks.check(
            "receipt-rationale-falsifier",
            bool(plan["children"][0]["compatibility"]["rationale"])
            and bool(plan["children"][0]["compatibility"]["falsifier"]),
            expected=True,
            observed=plan["children"][0]["compatibility"],
        )
    elif slug == "packing-generic-merge-refused":
        inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0), v2_synthetic_target(1)]
        )
        authority = v2_synthetic_authority(inventory)
        plan, _ = v2_build_review_plan(
            inventory,
            authority,
            max_targets=10,
        )
        checks.check(
            "no-receipt-singletons",
            len(plan["children"]) == 2
            and all(len(child["target_ids"]) == 1 for child in plan["children"]),
            expected=2,
            observed=len(plan["children"]),
        )
    elif slug == "packing-rationale-falsifier":
        singleton, _, _ = v2_plan_for_count(1, max_targets=10)
        merged, _, _ = v2_plan_for_count(2, max_targets=10)
        checks.check(
            "singleton-rationale",
            bool(singleton["children"][0]["compatibility"]["rationale"])
            and bool(singleton["children"][0]["compatibility"]["falsifier"]),
            expected=True,
            observed=singleton["children"][0]["compatibility"],
        )
        checks.check(
            "merge-witness-rationale",
            all(
                witness.get("rationale") and witness.get("falsifier")
                for witness in merged["packing_witnesses"]
            ),
            expected=True,
            observed=merged["packing_witnesses"],
        )
    elif slug == "packing-target-cap-10-25":
        for cap, population, expected_children in (
            (10, 10, 1),
            (10, 11, 2),
            (25, 25, 1),
            (25, 26, 2),
        ):
            plan, _, _ = v2_plan_for_count(population, max_targets=cap)
            checks.check(
                f"cap-{cap}-population-{population}",
                len(plan["children"]) == expected_children,
                expected=expected_children,
                observed=len(plan["children"]),
            )
        inventory = v2_synthetic_inventory([v2_synthetic_target(0)])
        authority = v2_synthetic_authority(inventory)
        checks.refuses(
            "configured-cap-26",
            UsageRefused,
            lambda: v2_build_review_plan(
                inventory,
                authority,
                max_targets=26,
            ),
            contains="1..25",
        )
    elif slug == "packing-minutes-479-480-481":
        for minutes in (479, 480):
            inventory = v2_synthetic_inventory(
                [v2_synthetic_target(0, review_minutes=minutes)]
            )
            authority = v2_synthetic_authority(inventory)
            plan, optional = v2_build_review_plan(
                inventory,
                authority,
                max_targets=10,
            )
            checks.check(
                f"minutes-{minutes}-bounded",
                not optional
                and plan["children"][0]["review_minutes"] == minutes,
                expected=minutes,
                observed=plan["children"][0]["review_minutes"],
            )
        inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0, review_minutes=481)]
        )
        authority = v2_synthetic_authority(inventory)
        plan, optional = v2_build_review_plan(
            inventory,
            authority,
            max_targets=10,
        )
        checks.check(
            "minutes-481-oversize",
            plan["children"][0]["review_minutes"] == 480
            and plan["work"]["total_review_minutes"] == 481
            and len(optional) == 1,
            expected={"bounded": 480, "underlying": 481, "optional": 1},
            observed={
                "bounded": plan["children"][0]["review_minutes"],
                "underlying": plan["work"]["total_review_minutes"],
                "optional": len(optional),
            },
        )
    elif slug == "packing-transport-cap-boundaries":
        inventory = v2_synthetic_inventory([v2_synthetic_target(0)])
        authority = v2_synthetic_authority(inventory)
        plan, _ = v2_build_review_plan(inventory, authority, max_targets=10)
        child = plan["children"][0]
        v2_validate_child_payload(child)
        checks.check(
            "baseline-transport-valid",
            True,
            expected="valid",
            observed=child["semantic_root"],
        )
        oversized = dict(child)
        description = dict(child["description_file_artifact"])
        description["content"] = "x" * (V2_CHILD_DESCRIPTION_CAP + 1)
        description["bytes"] = len(description["content"])
        description["root"] = text_root(description["content"])
        oversized["description_file_artifact"] = description
        oversized["description_root"] = description["root"]
        oversized = v2_rooted(oversized)
        checks.refuses(
            "description-cap-plus-one",
            EvidenceFailed,
            lambda: v2_validate_child_payload(oversized),
            contains="description",
        )
    elif slug == "packing-exact-small-optimum":
        for count in range(1, 14):
            plan, _, _ = v2_plan_for_count(count, max_targets=3)
            witness = plan["packing_witnesses"][0]
            expected_children = math.ceil(count / 3)
            checks.check(
                f"exact-count-{count:02d}",
                witness["algorithm"] == "EXACT_SUBSET_PARTITION"
                and witness["exact_optimality_claim"] is True
                and witness["objective"]["child_count"] == expected_children,
                expected={
                    "algorithm": "EXACT_SUBSET_PARTITION",
                    "children": expected_children,
                },
                observed={
                    "algorithm": witness["algorithm"],
                    "children": witness["objective"]["child_count"],
                },
            )
        minute_loads = (240, 240, 160, 160, 80, 80)
        byte_loads = (900, 100, 800, 200, 700, 300)
        inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    index,
                    review_minutes=minutes,
                    retained_payload_bytes=byte_loads[index],
                )
                for index, minutes in enumerate(minute_loads)
            ]
        )
        authority = v2_synthetic_authority(inventory, compatible=True)
        authority_by_id = {
            row["target_id"]: row for row in authority["decisions"]
        }
        rows = [
            (target, authority_by_id[target["id"]])
            for target in inventory["rows"]
        ]

        def independent_load(
            group: Sequence[
                tuple[Mapping[str, Any], Mapping[str, Any]]
            ],
        ) -> tuple[int, int, int]:
            return (
                sum(int(decision["review_minutes"]) for _, decision in group),
                sum(int(target["retained_payload_bytes"]) for target, _ in group),
                len(group),
            )

        def independent_key(
            groups: Sequence[
                Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]
            ],
        ) -> tuple[Any, ...]:
            loads = [independent_load(group) for group in groups]
            return (
                len(groups),
                max(load[0] for load in loads),
                max(load[1] for load in loads),
                max(load[2] for load in loads),
                tuple(sorted(loads, reverse=True)),
                tuple(
                    sorted(
                        tuple(sorted(target["id"] for target, _ in group))
                        for group in groups
                    )
                ),
            )

        independent_best: tuple[Any, ...] | None = None

        def enumerate_partitions(
            index: int,
            groups: list[
                list[tuple[Mapping[str, Any], Mapping[str, Any]]]
            ],
        ) -> None:
            nonlocal independent_best
            if index == len(rows):
                candidate = independent_key(groups)
                if independent_best is None or candidate < independent_best:
                    independent_best = candidate
                return
            row = rows[index]
            for group_index in range(len(groups) + 1):
                if group_index == len(groups):
                    groups.append([row])
                    enumerate_partitions(index + 1, groups)
                    groups.pop()
                    continue
                proposed = [*groups[group_index], row]
                minutes, retained_bytes, target_count = independent_load(proposed)
                if (
                    target_count > 3
                    or minutes > V2_REVIEW_MINUTES_CAP
                    or retained_bytes > V2_CHILD_PAYLOAD_CAP
                ):
                    continue
                groups[group_index].append(row)
                enumerate_partitions(index + 1, groups)
                groups[group_index].pop()

        enumerate_partitions(0, [])
        actual_bins, actual_witness = v2_pack_group(rows, max_targets=3)
        actual_key = independent_key(actual_bins)
        checks.check(
            "independent-enumeration-confirms-varied-load-optimum",
            independent_best is not None
            and actual_key == independent_best
            and actual_witness["objective"]
            == v2_objective_document(actual_bins),
            expected=independent_best,
            observed=actual_key,
        )
    elif slug == "packing-large-gap-witness":
        plan, _, _ = v2_plan_for_count(14, max_targets=10)
        witness = plan["packing_witnesses"][0]
        checks.check(
            "large-witness-complete",
            witness["algorithm"] == "DETERMINISTIC_LPT_VECTOR_PACKING"
            and "lower_bound_vector" in witness
            and "achieved_objective" in witness
            and "gap_witness" in witness
            and witness["exact_optimality_claim"] is False,
            expected=True,
            observed=witness,
        )
    elif slug == "packing-order-invariant":
        for population, max_targets, expected_algorithm in (
            (8, 3, "EXACT_SUBSET_PARTITION"),
            (14, 3, "DETERMINISTIC_LPT_VECTOR_PACKING"),
        ):
            targets = [
                v2_synthetic_target(index) for index in range(population)
            ]
            first_inventory = v2_synthetic_inventory(targets)
            second_inventory = v2_synthetic_inventory(
                list(reversed(targets))
            )
            first_authority = v2_synthetic_authority(
                first_inventory,
                compatible=True,
            )
            second_authority = v2_synthetic_authority(
                second_inventory,
                compatible=True,
            )
            first, _ = v2_build_review_plan(
                first_inventory,
                first_authority,
                max_targets=max_targets,
            )
            second, _ = v2_build_review_plan(
                second_inventory,
                second_authority,
                max_targets=max_targets,
            )
            checks.check(
                f"input-order-invariant-{population}",
                first["semantic_root"] == second["semantic_root"]
                and first["packing_witnesses"][0]["algorithm"]
                == expected_algorithm,
                expected={
                    "root": first["semantic_root"],
                    "algorithm": expected_algorithm,
                },
                observed={
                    "root": second["semantic_root"],
                    "algorithm": second["packing_witnesses"][0]["algorithm"],
                },
            )
    elif slug == "packing-refinement-imbalance":
        inventory = v2_synthetic_inventory(
            [v2_synthetic_target(index) for index in range(4)]
        )
        merged = v2_synthetic_authority(inventory, compatible=True)
        merged_plan, _ = v2_build_review_plan(
            inventory,
            merged,
            max_targets=10,
        )
        refined = v2_synthetic_authority(inventory, compatible=False)
        refined_plan, _ = v2_build_review_plan(
            inventory,
            refined,
            max_targets=10,
        )
        checks.check(
            "refinement-never-remerges",
            len(merged_plan["children"]) == 1
            and len(refined_plan["children"]) == 4,
            expected=(1, 4),
            observed=(
                len(merged_plan["children"]),
                len(refined_plan["children"]),
            ),
        )
    elif slug == "packing-oversize-escalation":
        inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    0,
                    retained_payload_bytes=V2_CHILD_PAYLOAD_CAP + 1,
                )
            ]
        )
        authority = v2_synthetic_authority(inventory)
        plan, optional = v2_build_review_plan(
            inventory,
            authority,
            max_targets=10,
        )
        entry = plan["oversize_content"][0]
        full = strict_json_loads(
            next(iter(optional.values())),
            label="synthetic oversize",
            require_canonical=True,
        )
        checks.check(
            "oversize-registry-complete",
            set(entry) == V2_OVERSIZE_REGISTRY_FIELDS
            and full["bounded_incomplete_index"]["complete"] is False
            and entry["exceeded_caps"] == full["exceeded_caps"]
            and entry["exceeded_caps"]
            == v2_oversize_exceeded_caps(
                inventory["rows"][0],
                authority["decisions"][0],
            ),
            expected={
                "registry_fields": sorted(V2_OVERSIZE_REGISTRY_FIELDS),
                "bounded_index_complete": False,
                "exceeded_caps": [
                    "max_retained_child_payload_bytes"
                ],
            },
            observed={
                "registry_fields": sorted(entry),
                "bounded_index_complete": full[
                    "bounded_incomplete_index"
                ]["complete"],
                "exceeded_caps": [
                    row["cap"] for row in entry["exceeded_caps"]
                ],
                "full_root": full["semantic_root"],
            },
        )
        for route_name, authority_kwargs, expected_route in (
            (
                "manual",
                {"declared": True, "manual": True},
                "MANUAL_BR_REVIEW",
            ),
            (
                "future-automated",
                {
                    "declared": True,
                    "external_verdict": "VALID",
                    "conditional_verdict": "VALID",
                    "gate_verdict": "VALID",
                    "version": "0.3.0",
                    "allow_mechanical_fixture": True,
                },
                "AUTOMATED_CONDITIONAL",
            ),
        ):
            routed_authority = v2_synthetic_authority(
                inventory,
                **authority_kwargs,
            )
            routed_plan, _ = v2_build_review_plan(
                inventory,
                routed_authority,
                max_targets=10,
            )
            routed_child = routed_plan["children"][0]
            v2_validate_child_payload(routed_child)
            checks.check(
                f"oversize-{route_name}-route-preserved",
                routed_child["disposition_workflow"]
                == "OVERSIZE_REVIEW_REQUIRED"
                and routed_child["remediation_route"] == expected_route
                and routed_child["semantic_review_action"]
                == routed_authority["decisions"][0][
                    "semantic_review_action"
                ],
                expected={
                    "workflow": "OVERSIZE_REVIEW_REQUIRED",
                    "route": expected_route,
                },
                observed={
                    "workflow": routed_child["disposition_workflow"],
                    "route": routed_child["remediation_route"],
                    "semantic_action": routed_child[
                        "semantic_review_action"
                    ],
                },
            )
    else:
        raise EvidenceFailed(f"no packing executor for {slug}")
    return checks.finish(parameters)


def v2_history_fixture(
    manifest: Mapping[str, Any],
    *,
    legacy: bool = False,
    missing_modern_event: bool = False,
    conflicting_close: bool = False,
    candidate_consumers: bool = False,
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    list[dict[str, Any]],
    dict[str, Any],
    dict[str, Any],
]:
    anchor_id = "fixture-anchor"
    anchor_closed_at = "2026-01-02T00:00:00.000000+00:00"
    anchor_raw = {
        "id": anchor_id,
        "title": "Fixture audit anchor",
        "issue_type": "task",
        "status": "closed",
        "priority": 2,
        "description": "Anchor source.",
        "acceptance_criteria": "Exact anchor.",
        "design": "",
        "notes": "See fixture-consumer." if candidate_consumers else "",
        "assignee": "fixture-assignee",
        "labels": [],
        "parent": "",
        "created_at": "2026-01-01T00:00:00+00:00",
        "created_by": "fixture-creator",
        "updated_at": "2026-01-02T00:00:00.002000+00:00",
        "closed_at": anchor_closed_at,
        "close_reason": "Fixture anchor completed.",
        "estimated_minutes": 5,
        "dependencies": [],
        "dependents": (
            [
                {
                    "id": "fixture-consumer",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 2,
                }
            ]
            if candidate_consumers
            else []
        ),
    }
    anchor = v2_full_issue_projection(anchor_raw)
    anchor_events = [
        {
            "id": 2,
            "event_type": "closed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00.002000+00:00",
            "comment": "Fixture anchor completed.",
        },
        {
            "id": 1,
            "event_type": "status_changed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00.001000+00:00",
            "old_value": "open",
            "new_value": "closed",
        },
    ]
    if conflicting_close:
        anchor_events = [
            {
                "id": 3,
                "event_type": "closed",
                "actor": "other-closer",
                "timestamp": "2026-01-02T00:00:00.003000+00:00",
                "comment": "Fixture anchor completed.",
            },
            *anchor_events,
        ]
    anchor_audit = v2_normalize_audit_document(
        {"issue_id": anchor_id, "events": anchor_events},
        issue_id=anchor_id,
    )
    all_issues = [anchor]
    audit_documents = [anchor_audit]
    target_id = anchor_id
    if missing_modern_event:
        modern_id = "fixture-modern-missing-close"
        modern_raw = {
            **anchor_raw,
            "id": modern_id,
            "title": "Fixture modern close without audit evidence",
            "closed_at": "2026-01-03T00:00:00+00:00",
            "updated_at": "2026-01-03T00:00:00+00:00",
            "close_reason": "Modern fixture completed.",
            "dependents": [],
        }
        modern_issue = v2_full_issue_projection(modern_raw)
        modern_audit = v2_normalize_audit_document(
            {"issue_id": modern_id, "events": []},
            issue_id=modern_id,
        )
        all_issues.append(modern_issue)
        audit_documents.append(modern_audit)
        target_id = modern_id
    if legacy:
        legacy_id = "fixture-legacy"
        legacy_raw = {
            **anchor_raw,
            "id": legacy_id,
            "title": "Fixture legacy close",
            "closed_at": "2026-01-01T12:00:00+00:00",
            "close_reason": "Legacy fixture completed.",
            "updated_at": "2026-01-03T00:00:00+00:00",
            "notes": "Later non-close audit metadata.",
            "dependents": [],
        }
        legacy_issue = v2_full_issue_projection(legacy_raw)
        legacy_audit = v2_normalize_audit_document(
            {
                "issue_id": legacy_id,
                "events": [
                    {
                        "id": 4,
                        "event_type": "label_added",
                        "actor": "later-agent",
                        "timestamp": "2026-01-03T00:00:00+00:00",
                        "comment": "Added label after legacy close.",
                    }
                ],
            },
            issue_id=legacy_id,
        )
        all_issues.append(legacy_issue)
        audit_documents.append(legacy_audit)
        target_id = legacy_id
    target = v2_synthetic_target(
        0,
        issue_id=target_id,
        status="closed",
        disposition="HISTORICAL_IMMUTABLE_REVIEW",
    )
    issue_by_id = {row["id"]: row for row in all_issues}
    target = dict(target)
    target["field_roots"] = issue_by_id[target_id]["field_roots"]
    target["target_root"] = semantic_root(
        {
            "id": target_id,
            "field_roots": target["field_roots"],
            "status": "closed",
        }
    )
    target = v2_rooted(target)
    inventory = v2_synthetic_inventory([target])
    authority = v2_synthetic_authority(inventory)
    audit_capture = v2_rooted(
        {
            "capture_count": 2,
            "worker_bound": 8,
            "issue_ids": sorted(row["issue_id"] for row in audit_documents),
            "documents": sorted(
                audit_documents, key=lambda row: row["issue_id"]
            ),
            "command_receipts": [],
            "raw_stream_bodies_retained": False,
            "no_claim": "synthetic audit capture",
        }
    )
    anchor_timestamp = v2_parse_timestamp(
        anchor_closed_at,
        label="fixture anchor",
    )
    legacy_rows = sorted(
        [
            {
                "id": issue["id"],
                "closed_at": issue["closed_at"],
                "close_reason_root": text_root(issue["close_reason"]),
            }
            for issue in all_issues
            if v2_parse_timestamp(
                issue["closed_at"],
                label=f"fixture {issue['id']}",
            )
            < anchor_timestamp
        ],
        key=lambda row: row["id"],
    )
    contract = dict(manifest["history_contract"])
    contract.update(
        {
            "legacy_coverage_anchor_issue": anchor_id,
            "legacy_coverage_anchor_closed_at": anchor_closed_at,
            "legacy_coverage_anchor_status_event_id": 1,
            "legacy_coverage_anchor_close_event_id": 2,
            "legacy_coverage_count": len(legacy_rows),
            "legacy_coverage_rows_root": semantic_root(legacy_rows),
            "known_pair_max_skew_ms": 1_000,
        }
    )
    return inventory, authority, all_issues, audit_capture, contract


def v2_execute_history_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "history-zero-movement", "slug": slug}
    if slug == "history-known-closer":
        inventory, authority, issues, audit, contract = v2_history_fixture(
            manifest
        )
        history = v2_build_history(
            source_root=semantic_root({"fixture": "known"}),
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=audit,
            history_contract=contract,
        )
        row = history["rows"][0]
        checks.check(
            "known-closer-exact",
            row["closer_state"] == "KNOWN"
            and row["close_actor"] == "fixture-closer"
            and row["close_actor_source"] == "br.audit.log.closed.actor"
            and row["audit_event_root"],
            expected=("KNOWN", "fixture-closer"),
            observed=(
                row["closer_state"],
                row["close_actor"],
                row["audit_event_root"],
            ),
        )
    elif slug == "history-legacy-closer":
        inventory, authority, issues, audit, contract = v2_history_fixture(
            manifest,
            legacy=True,
        )
        history = v2_build_history(
            source_root=semantic_root({"fixture": "legacy"}),
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=audit,
            history_contract=contract,
        )
        row = history["rows"][0]
        checks.check(
            "legacy-actor-nodata",
            row["closer_state"] == "LEGACY_UNAVAILABLE"
            and row["close_actor"] is None
            and row["close_actor_source"] == contract["legacy_coverage_rows_root"],
            expected=("LEGACY_UNAVAILABLE", None),
            observed=(row["closer_state"], row["close_actor"]),
        )
    elif slug == "history-unknown-conflicted-closer":
        args = v2_history_fixture(manifest, conflicting_close=True)
        checks.refuses(
            "conflicting-closers-refused",
            EvidenceFailed,
            lambda: v2_build_history(
                source_root=semantic_root({"fixture": "conflict"}),
                inventory=args[0],
                authority=args[1],
                all_issues=args[2],
                audit_capture=args[3],
                history_contract=args[4],
            ),
            contains="conflicted",
        )
        missing_actor = {
            "issue_id": "x",
            "events": [
                {
                    "id": 2,
                    "event_type": "closed",
                    "timestamp": "2026-01-02T00:00:00+00:00",
                },
                {
                    "id": 1,
                    "event_type": "status_changed",
                    "actor": "creator",
                    "timestamp": "2026-01-01T23:59:59+00:00",
                    "new_value": "closed",
                },
            ],
        }
        normalized = v2_normalize_audit_document(
            missing_actor,
            issue_id="x",
        )
        checks.check(
            "missing-actor-retained-empty",
            "actor" not in normalized["events"][0],
            expected="NoData actor",
            observed=normalized["events"][0],
        )
    elif slug == "history-timestamp-reason":
        valid_values = (
            "2026-01-01T00:00:00Z",
            "2026-01-01T00:00:00.123456+00:00",
            "2026-01-01T01:00:00+01:00",
        )
        for index, value in enumerate(valid_values):
            parsed = v2_parse_timestamp(value, label="fixture")
            checks.check(
                f"valid-timestamp-{index}",
                parsed.tzinfo is not None,
                expected=True,
                observed=str(parsed),
            )
        for index, value in enumerate(("", "2026-01-01", "not-time")):
            checks.refuses(
                f"invalid-timestamp-{index}",
                EvidenceFailed,
                lambda value=value: v2_parse_timestamp(value, label="fixture"),
                contains="timestamp",
            )
        inventory, authority, issues, audit, contract = v2_history_fixture(
            manifest,
            missing_modern_event=True,
        )
        selected_id = inventory["rows"][0]["id"]
        selected_index = next(
            index for index, issue in enumerate(issues) if issue["id"] == selected_id
        )
        issues[selected_index] = dict(issues[selected_index])
        issues[selected_index]["close_reason"] = ""
        checks.refuses(
            "missing-reason-refused",
            EvidenceFailed,
            lambda: v2_build_history(
                source_root=semantic_root({"fixture": "reason"}),
                inventory=inventory,
                authority=authority,
                all_issues=issues,
                audit_capture=audit,
                history_contract=contract,
            ),
            contains="close metadata",
        )
    elif slug == "history-missing-audit-event":
        args = v2_history_fixture(manifest, missing_modern_event=True)
        checks.refuses(
            "modern-missing-close-refused",
            EvidenceFailed,
            lambda: v2_build_history(
                source_root=semantic_root({"fixture": "missing"}),
                inventory=args[0],
                authority=args[1],
                all_issues=args[2],
                audit_capture=args[3],
                history_contract=args[4],
            ),
            contains="conflicted",
        )
    elif slug == "history-duplicate-conflicting-order":
        duplicate = {
            "issue_id": "x",
            "events": [
                {
                    "id": 1,
                    "event_type": "closed",
                    "actor": "a",
                    "timestamp": "2026-01-01T00:00:00Z",
                },
                {
                    "id": 1,
                    "event_type": "closed",
                    "actor": "a",
                    "timestamp": "2026-01-01T00:00:00Z",
                },
            ],
        }
        checks.refuses(
            "duplicate-event-id",
            EvidenceFailed,
            lambda: v2_normalize_audit_document(duplicate, issue_id="x"),
            contains="duplicate",
        )
        reordered = {
            "issue_id": "x",
            "events": [
                {
                    "id": 1,
                    "event_type": "created",
                    "actor": "a",
                    "timestamp": "2026-01-01T00:00:00Z",
                },
                {
                    "id": 2,
                    "event_type": "closed",
                    "actor": "a",
                    "timestamp": "2026-01-02T00:00:00Z",
                },
            ],
        }
        checks.refuses(
            "reordered-event-id",
            EvidenceFailed,
            lambda: v2_normalize_audit_document(reordered, issue_id="x"),
            contains="order",
        )
    elif slug == "history-consumer-candidates":
        inventory, authority, issues, audit, contract = v2_history_fixture(
            manifest,
            candidate_consumers=True,
        )
        history = v2_build_history(
            source_root=semantic_root({"fixture": "consumers"}),
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=audit,
            history_contract=contract,
        )
        row = history["rows"][0]
        checks.check(
            "candidate-not-reviewed",
            "fixture-consumer" in row["candidate_consumers"]
            and row["reviewed_consumers"] == [],
            expected={"candidate": "fixture-consumer", "reviewed": []},
            observed={
                "candidate": row["candidate_consumers"],
                "reviewed": row["reviewed_consumers"],
            },
        )
    elif slug == "history-immutable-relations":
        inventory, authority, issues, audit, contract = v2_history_fixture(
            manifest
        )
        before = semantic_root(issues)
        v2_build_history(
            source_root=semantic_root({"fixture": "immutable"}),
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=audit,
            history_contract=contract,
        )
        after = semantic_root(issues)
        checks.check(
            "closed-source-unchanged",
            before == after,
            expected=before,
            observed=after,
        )
    elif slug == "zero-all-priority-status-cells":
        statuses = ["open", "in_progress", "blocked", "deferred", "closed"]
        targets = [
            v2_synthetic_target(
                priority * 5 + status_index,
                priority=priority,
                status=status,
            )
            for priority in range(5)
            for status_index, status in enumerate(statuses)
        ]
        inventory = v2_synthetic_inventory(targets)
        zero = v2_build_zero_sets(
            source_root=semantic_root({"fixture": "cells"}),
            inventory=inventory,
            prior_campaign=v2_empty_prior_campaign(),
        )
        checks.check(
            "all-25-cells-covered",
            len(zero["cells"]) == 25
            and zero["counts"]["issues"] == 25
            and zero["counts"]["zero_receipts"] == 0,
            expected={"cells": 25, "issues": 25, "zero": 0},
            observed=zero["counts"],
        )
        sparse_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(100, priority=2, status="open")]
        )
        sparse_source_root = semantic_root({"fixture": "sparse-cells"})
        sparse = v2_build_zero_sets(
            source_root=sparse_source_root,
            inventory=sparse_inventory,
            prior_campaign=v2_empty_prior_campaign(),
        )
        sparse_zero_receipts = [
            cell["zero_receipt"]
            for cell in sparse["cells"]
            if cell["zero_receipt"] is not None
        ]
        sparse_roots_valid = True
        for receipt in sparse_zero_receipts:
            try:
                verify_semantic_root(
                    receipt,
                    label="sparse zero receipt",
                )
            except HarnessError:
                sparse_roots_valid = False
        checks.check(
            "sparse-24-zero-receipts-rooted",
            len(sparse_zero_receipts) == 24
            and sparse_roots_valid
            and all(
                receipt["count"] == 0
                and receipt["source_root"] == sparse_source_root
                and receipt["inventory_root"]
                == sparse_inventory["semantic_root"]
                for receipt in sparse_zero_receipts
            ),
            expected={"zero_receipts": 24, "issues": 1},
            observed=sparse["counts"],
        )
        empty_inventory = v2_synthetic_inventory([])
        empty = v2_build_zero_sets(
            source_root=semantic_root({"fixture": "empty-cells"}),
            inventory=empty_inventory,
            prior_campaign=v2_empty_prior_campaign(),
        )
        checks.check(
            "empty-all-cells-have-zero-receipts",
            empty["counts"]
            == {
                "cells": 25,
                "zero_receipts": 25,
                "issues": 0,
                "scope_successors": 0,
                "movements": 0,
            }
            and all(cell["zero_receipt"] is not None for cell in empty["cells"]),
            expected={"cells": 25, "zero_receipts": 25, "issues": 0},
            observed=empty["counts"],
        )

        def reroot_zero_fixture(
            document: Mapping[str, Any],
            *,
            cell_index: int | None = None,
            receipt_changed: bool = False,
        ) -> dict[str, Any]:
            mutated = json.loads(canonical_bytes(document))
            if cell_index is not None:
                if receipt_changed:
                    receipt = mutated["cells"][cell_index]["zero_receipt"]
                    if isinstance(receipt, dict):
                        mutated["cells"][cell_index][
                            "zero_receipt"
                        ] = v2_rooted(receipt)
                mutated["cells"][cell_index] = v2_rooted(
                    mutated["cells"][cell_index]
                )
            return v2_rooted(mutated)

        semantic_mutations: list[tuple[str, dict[str, Any], str]] = []

        wrong_coordinate = json.loads(canonical_bytes(sparse))
        wrong_coordinate["cells"][0]["zero_receipt"]["priority"] = 1
        wrong_coordinate = reroot_zero_fixture(
            wrong_coordinate,
            cell_index=0,
            receipt_changed=True,
        )
        semantic_mutations.append(
            ("wrong-zero-coordinate", wrong_coordinate, "bindings differ")
        )

        wrong_source = json.loads(canonical_bytes(sparse))
        wrong_source["cells"][0]["zero_receipt"]["source_root"] = semantic_root(
            {"wrong": "source"}
        )
        wrong_source = reroot_zero_fixture(
            wrong_source,
            cell_index=0,
            receipt_changed=True,
        )
        semantic_mutations.append(
            ("wrong-zero-source-root", wrong_source, "bindings differ")
        )

        missing_receipt = json.loads(canonical_bytes(sparse))
        missing_receipt["cells"][0]["zero_receipt"] = None
        missing_receipt = reroot_zero_fixture(
            missing_receipt,
            cell_index=0,
        )
        semantic_mutations.append(
            ("missing-zero-receipt", missing_receipt, "lacks a zero receipt")
        )

        populated_receipt = json.loads(canonical_bytes(sparse))
        populated_index = 2 * len(STATUS_SCOPES)
        populated_cell = populated_receipt["cells"][populated_index]
        populated_cell["zero_receipt"] = v2_rooted(
            {
                "schema": V2_ZERO_RECEIPT_SCHEMA,
                "priority": populated_cell["priority"],
                "status": populated_cell["status"],
                "membership_root": populated_cell["membership_root"],
                "issue_ids_root": semantic_root([]),
                "source_root": sparse_source_root,
                "inventory_root": sparse_inventory["semantic_root"],
                "campaign_epoch_root": sparse_inventory[
                    "campaign_epoch_root"
                ],
                "partition_issue_ids_root": sparse[
                    "partition_issue_ids_root"
                ],
                "count": 0,
                "no_claim": "maliciously rerooted populated-cell fixture",
            }
        )
        populated_receipt = reroot_zero_fixture(
            populated_receipt,
            cell_index=populated_index,
        )
        semantic_mutations.append(
            (
                "receipt-on-populated-cell",
                populated_receipt,
                "carries a zero receipt",
            )
        )

        reordered_cells = json.loads(canonical_bytes(sparse))
        reordered_cells["cells"][0], reordered_cells["cells"][1] = (
            reordered_cells["cells"][1],
            reordered_cells["cells"][0],
        )
        reordered_cells = v2_rooted(reordered_cells)
        semantic_mutations.append(
            ("reordered-zero-cells", reordered_cells, "membership differs")
        )

        wrong_counts = json.loads(canonical_bytes(sparse))
        wrong_counts["counts"]["zero_receipts"] = 23
        wrong_counts = v2_rooted(wrong_counts)
        semantic_mutations.append(
            ("wrong-zero-count", wrong_counts, "counts differ")
        )

        for mutation_id, malformed, diagnostic in semantic_mutations:
            checks.refuses(
                mutation_id,
                EvidenceFailed,
                lambda malformed=malformed: v2_validate_zero_sets(
                    malformed,
                    source_root=sparse_source_root,
                    inventory=sparse_inventory,
                    prior_campaign=v2_empty_prior_campaign(),
                ),
                contains=diagnostic,
                projection=lambda malformed=malformed: malformed,
                projection_label="ZERO_SET_ARTIFACT",
            )
    elif slug in {
        "movement-cross-lane",
        "movement-live-to-history",
        "movement-history-to-live",
    }:
        transitions = {
            "movement-cross-lane": ("open", 1, "blocked", 2, "MOVED_TO_LANE"),
            "movement-live-to-history": (
                "open",
                1,
                "closed",
                1,
                "MOVED_TO_HISTORY",
            ),
            "movement-history-to-live": (
                "closed",
                1,
                "open",
                1,
                "MOVED_FROM_HISTORY",
            ),
        }
        before_status, before_priority, after_status, after_priority, expected_class = (
            transitions[slug]
        )
        current_target = v2_synthetic_target(
            0,
            status=after_status,
            priority=after_priority,
            missing_sections=(
                ()
                if slug == "movement-live-to-history"
                else ("## Acceptance Criteria",)
            ),
        )
        current_universe = [current_target]
        inventory = v2_synthetic_inventory(
            []
            if slug == "movement-live-to-history"
            else [current_target]
        )
        current_id = current_target["id"]
        prior = v2_rooted(
            {
                "state": "PROVIDED",
                "bundle_path": "target/v2-fixture/prior-run",
                "terminal_root": semantic_root({"terminal": "prior"}),
                "inventory_root": semantic_root({"inventory": "prior"}),
                "campaign_epoch_root": semantic_root(
                    {"campaign": "prior"}
                ),
                "rows": [
                    {
                        "id": current_id,
                        "status": before_status,
                        "priority": before_priority,
                        "target_root": semantic_root({"before": current_id}),
                        "destination": (
                            "history-v2.json"
                            if before_status == "closed"
                            else "review-plan-v2.json"
                        ),
                    }
                ],
                "no_claim": "synthetic immutable prior evidence for movement testing",
            }
        )
        zero = v2_build_zero_sets(
            source_root=semantic_root({"fixture": slug}),
            inventory=inventory,
            prior_campaign=prior,
            current_universe=current_universe,
        )
        movement = zero["movements"][0]
        checks.check(
            "movement-class-lineage",
            movement["class"] == expected_class
            and movement["successor_lineage_root"].startswith("sha256-v1:")
            and movement["current_universe_root"]
            == zero["current_universe_root"]
            and movement["destination_root_kind"]
            == (
                "FULL_UNIVERSE_SUCCESSOR"
                if slug == "movement-live-to-history"
                else "INVENTORY_TARGET"
            )
            and zero["current_universe_count"] == 1
            and len(zero["scope_successors"])
            == (1 if slug == "movement-live-to-history" else 0),
            expected={
                "class": expected_class,
                "destination_root_kind": (
                    "FULL_UNIVERSE_SUCCESSOR"
                    if slug == "movement-live-to-history"
                    else "INVENTORY_TARGET"
                ),
                "universe_count": 1,
            },
            observed={
                "movement": movement,
                "universe_count": zero["current_universe_count"],
                "scope_successors": zero["scope_successors"],
            },
        )
        malformed = json.loads(canonical_bytes(zero))
        malformed["movements"][0]["class"] = "MOVED_TO_LANE"
        if expected_class == "MOVED_TO_LANE":
            malformed["movements"][0]["class"] = "MOVED_TO_HISTORY"
        malformed["movements"][0] = v2_rooted(
            malformed["movements"][0]
        )
        malformed = v2_rooted(malformed)
        checks.refuses(
            "rerooted-movement-class-refused",
            EvidenceFailed,
            lambda: v2_validate_zero_sets(
                malformed,
                source_root=zero["source_root"],
                inventory=inventory,
                prior_campaign=prior,
                current_universe=current_universe,
            ),
            contains="independently reconstructed",
            projection=lambda: malformed,
            projection_label="MOVEMENT_ARTIFACT",
        )
        for field, replacement in (
            ("destination_root_kind", "INVENTORY_TARGET"),
            (
                "current_universe_root",
                semantic_root({"forged": "universe"}),
            ),
        ):
            if movement[field] == replacement:
                replacement = (
                    "FULL_UNIVERSE_SUCCESSOR"
                    if field == "destination_root_kind"
                    else semantic_root({"forged": "other-universe"})
                )
            tampered = json.loads(canonical_bytes(zero))
            tampered["movements"][0][field] = replacement
            tampered["movements"][0] = v2_rooted(
                tampered["movements"][0]
            )
            tampered = v2_rooted(tampered)
            checks.refuses(
                f"rerooted-movement-{field}-refused",
                EvidenceFailed,
                lambda tampered=tampered: v2_validate_zero_sets(
                    tampered,
                    source_root=zero["source_root"],
                    inventory=inventory,
                    prior_campaign=prior,
                    current_universe=current_universe,
                ),
                contains="independently reconstructed",
            )
        if slug == "movement-live-to-history":
            checks.refuses(
                "prior-target-absent-current-universe-refused",
                InputRefused,
                lambda: v2_build_zero_sets(
                    source_root=zero["source_root"],
                    inventory=inventory,
                    prior_campaign=prior,
                    current_universe=[],
                ),
                contains="absent from the current source universe",
            )
            nonclosed_successor = dict(current_target)
            nonclosed_successor.pop("semantic_root", None)
            nonclosed_successor["status"] = "open"
            nonclosed_successor = v2_rooted(nonclosed_successor)
            checks.refuses(
                "prior-target-nonclosed-out-of-scope-refused",
                InputRefused,
                lambda: v2_build_zero_sets(
                    source_root=zero["source_root"],
                    inventory=inventory,
                    prior_campaign=prior,
                    current_universe=[nonclosed_successor],
                ),
                contains="without a clean closed successor",
            )
    else:
        raise EvidenceFailed(f"no history executor for {slug}")
    return checks.finish(parameters)


def v2_synthetic_payloads(
    manifest: Mapping[str, Any],
    *,
    oversize: bool = False,
) -> tuple[dict[str, bytes], tuple[Any, ...]]:
    components = v2_synthetic_bundle_components(
        manifest,
        target_count=1 if oversize else 2,
        oversize=oversize,
    )
    source, inventory, authority, review, history, zero, optional = components
    reproduction = [
        str(SCRIPT_REL),
        "--review-plan",
        "--artifact-root",
        "target/v2-fixture",
        "--artifact-dir",
        "run",
    ]
    payloads = v2_bundle_payloads(
        mode="review-plan",
        subject_mode="review-plan",
        artifact_root="target/v2-fixture",
        artifact_dir="run",
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review,
        history=history,
        zero_sets=zero,
        optional_payloads=optional,
        reproduction=reproduction,
    )
    return payloads, components


def v2_execute_artifact_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "artifact-log-replay", "slug": slug}
    if slug == "artifact-review-base-set":
        payloads, components = v2_synthetic_payloads(manifest)
        checks.check(
            "review-nine-base-files",
            set(V2_RUN_ARTIFACTS).issubset(payloads)
            and len(set(V2_RUN_ARTIFACTS)) == 9
            and components[3]["state"] == "POPULATED"
            and components[4]["state"] == "NOT_REQUESTED",
            expected={"base": 9, "review": "POPULATED", "history": "NOT_REQUESTED"},
            observed={
                "base": len(set(V2_RUN_ARTIFACTS) & set(payloads)),
                "review": components[3]["state"],
                "history": components[4]["state"],
            },
        )
    elif slug == "artifact-history-base-set":
        inventory, authority, issues, audit, contract = v2_history_fixture(
            manifest
        )
        source = v2_minimal_source(
            manifest_root=manifest["semantic_root"],
            subject="history-bundle",
        )
        review = v2_not_requested(
            schema=V2_REVIEW_PLAN_SCHEMA,
            mode="history-plan",
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="review-plan",
        )
        history = v2_build_history(
            source_root=source["semantic_root"],
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=audit,
            history_contract=contract,
        )
        zero = v2_build_zero_sets(
            source_root=source["semantic_root"],
            inventory=inventory,
            prior_campaign=v2_empty_prior_campaign(),
        )
        payloads = v2_bundle_payloads(
            mode="history-plan",
            subject_mode="history-plan",
            artifact_root="target/v2-fixture",
            artifact_dir="history-run",
            source=source,
            inventory=inventory,
            authority=authority,
            review_plan=review,
            history=history,
            zero_sets=zero,
            optional_payloads={},
            reproduction=["script", "--history-plan"],
        )
        checks.check(
            "history-nine-base-files",
            set(payloads) == set(V2_RUN_ARTIFACTS)
            and history["state"] == "POPULATED"
            and review["state"] == "NOT_REQUESTED",
            expected={"files": 9, "history": "POPULATED", "review": "NOT_REQUESTED"},
            observed={
                "files": len(payloads),
                "history": history["state"],
                "review": review["state"],
            },
        )
    elif slug == "artifact-not-requested-projection":
        document = v2_not_requested(
            schema=V2_HISTORY_SCHEMA,
            mode="review-plan",
            source_root=semantic_root({"source": 1}),
            inventory_root=semantic_root({"inventory": 1}),
            projection="history",
        )
        expected = {
            "schema",
            "state",
            "mode",
            "projection",
            "source_root",
            "inventory_root",
            "rows",
            "no_claim",
            "semantic_root",
        }
        checks.check(
            "not-requested-closed-schema",
            set(document) == expected
            and document["state"] == "NOT_REQUESTED"
            and document["rows"] == [],
            expected=sorted(expected),
            observed=sorted(document),
        )
        mutated = dict(document)
        mutated["state"] = "POPULATED"
        checks.check(
            "empty-populated-root-differs",
            semantic_root(
                {key: value for key, value in mutated.items() if key != "semantic_root"}
            )
            != document["semantic_root"],
            expected="different root",
            observed=semantic_root(
                {key: value for key, value in mutated.items() if key != "semantic_root"}
            ),
        )
    elif slug == "artifact-oversize-inventory":
        payloads, components = v2_synthetic_payloads(
            manifest,
            oversize=True,
        )
        review = components[3]
        entry = review["oversize_content"][0]
        optional_name = entry["relative_path"]
        checks.check(
            "registered-optional-exact",
            optional_name in payloads
            and entry["byte_length"] == len(payloads[optional_name])
            and entry["aggregate_cap_accounting"] == len(payloads[optional_name]),
            expected=entry["byte_length"],
            observed=len(payloads[optional_name]),
        )
        checks.check(
            "optional-roots-complete",
            bool(entry["target_roots"])
            and bool(entry["field_roots"])
            and bool(entry["clause_roots"]),
            expected=True,
            observed=entry,
        )
    elif slug == "artifact-no-overwrite-partial":
        checks.refuses(
            "existing-output-refused",
            EvidenceFailed,
            lambda: require_fresh_run_dir(
                REPO_ROOT / "target",
                label="fixture output",
            ),
            contains="already exists",
        )
        prefix = {"source-v2.json": b"{}\n"}
        checks.check(
            "partial-prefix-not-complete",
            "terminal.json" not in prefix,
            expected="terminal absent",
            observed=sorted(prefix),
        )
        for error_type in (InputRefused, NoData, EvidenceFailed):
            artifact_root, artifact_dir = v2_persistent_e2e_location(
                manifest,
                label=f"refusal-{error_type.terminal.lower()}",
            )
            refusal_payloads, failure = v2_refusal_bundle_payloads(
                mode="review-plan",
                artifact_root=artifact_root,
                artifact_dir=artifact_dir,
                manifest=manifest,
                error=error_type("bounded semantic refusal fixture"),
                stage="selected_projection",
                available_roots={
                    "source": None,
                    "inventory": None,
                    "authority": None,
                    "review_plan": None,
                    "history": None,
                    "zero_sets": None,
                },
                argv=[str(SCRIPT_REL), "--review-plan"],
            )
            (
                _,
                retained_refusal,
                refusal_terminal,
                refusal_events,
            ) = v2_publish_and_read_persistent_fixture(
                artifact_root=artifact_root,
                artifact_dir=artifact_dir,
                payloads=refusal_payloads,
            )
            validated = v2_validate_refusal_bundle(
                artifact_root=artifact_root,
                input_dir=artifact_dir,
                payloads=retained_refusal,
                terminal=refusal_terminal,
                events=refusal_events,
                accepted_manifest=manifest,
            )
            checks.check(
                f"complete-non-green-{error_type.terminal}",
                set(refusal_payloads) == set(V2_RUN_ARTIFACTS)
                and refusal_terminal["bundle_state"]
                == "COMPLETE_NON_GREEN"
                and refusal_terminal["optional_content_registry"] == []
                and refusal_terminal["failure_root"]
                == failure["semantic_root"]
                and validated["terminal"] == error_type.terminal
                and validated["complete_green_prefix"] is False,
                expected={
                    "files": 9,
                    "terminal": error_type.terminal,
                    "green": False,
                },
                observed={
                    "files": len(refusal_payloads),
                    "terminal": validated["terminal"],
                    "green": validated["complete_green_prefix"],
                },
            )
            replay_output = f"{artifact_dir}-forbidden-replay"
            replay_output_path = resolve_run_dir(
                artifact_root,
                replay_output,
                label="refusal replay output",
            )
            if replay_output_path.exists():
                raise EvidenceFailed(
                    "semantic-refusal replay unexpectedly has an output prefix"
                )
            try:
                v2_replay_bundle(
                    artifact_root=artifact_root,
                    input_dir=artifact_dir,
                    output_dir=replay_output,
                )
            except PublishedV2Refusal as replay_error:
                checks.check(
                    f"filesystem-replay-preserves-{error_type.terminal}",
                    replay_error.terminal == error_type.terminal
                    and replay_error.document["exit_code"]
                    == TERMINAL_EXIT[error_type.terminal]
                    and replay_error.document[
                        "replay_validated_without_output"
                    ]
                    is True
                    and not replay_output_path.exists(),
                    expected={
                        "terminal": error_type.terminal,
                        "exit_code": TERMINAL_EXIT[error_type.terminal],
                        "output_exists": False,
                    },
                    observed={
                        "terminal": replay_error.terminal,
                        "exit_code": replay_error.document["exit_code"],
                        "output_exists": replay_output_path.exists(),
                    },
                )
            else:
                raise EvidenceFailed(
                    "semantic-refusal replay incorrectly returned Pass"
                )
    elif slug == "artifact-membership-path-safety":
        for index, value in enumerate(
            ("../escape", "/absolute", "a//b", "a/./b", "a\\b", "e\u0301")
        ):
            checks.refuses(
                f"unsafe-member-{index}",
                InputRefused,
                lambda value=value: v2_safe_member(value, label="fixture"),
                contains="unsafe",
            )
        expected = sorted(V2_RUN_ARTIFACTS)
        extra = sorted([*V2_RUN_ARTIFACTS, "extra.json"])
        checks.check(
            "extra-membership-detected",
            expected != extra,
            expected=expected,
            observed=extra,
        )
        identities: dict[tuple[int, int], str] = {}
        v2_register_member_identity(
            identities,
            device=1,
            inode=100,
            link_count=1,
            relative="source-v2.json",
            kind="file",
        )
        identity_projection = lambda: [
            {
                "device": device,
                "inode": inode,
                "path": path,
            }
            for (device, inode), path in sorted(identities.items())
        ]
        checks.refuses(
            "inode-alias-refused",
            InputRefused,
            lambda: v2_register_member_identity(
                identities,
                device=1,
                inode=100,
                link_count=1,
                relative="inventory-v2.json",
                kind="file",
            ),
            contains="inode alias",
            projection=identity_projection,
            projection_label="BUNDLE_MEMBER_IDENTITIES",
        )
        checks.refuses(
            "external-hardlink-refused",
            InputRefused,
            lambda: v2_register_member_identity(
                identities,
                device=1,
                inode=101,
                link_count=2,
                relative="authority-v2.json",
                kind="file",
            ),
            contains="hard-link alias",
            projection=identity_projection,
            projection_label="BUNDLE_MEMBER_IDENTITIES",
        )
    elif slug == "log-assertion-argv-evidence":
        payloads, _ = v2_synthetic_payloads(manifest)
        events = v2_read_event_stream(payloads["events.jsonl"])
        checks.check(
            "events-have-required-evidence",
            all(
                event["case_id"]
                and event["assertion_id"] == event["executor_id"]
                and isinstance(event["argv"], list)
                and event["parameter_root"].startswith("sha256-v1:")
                for event in events
            ),
            expected=True,
            observed={
                "events": len(events),
                "root": semantic_root(events),
            },
        )
    elif slug == "log-raw-result-redaction":
        hostile = [
            "/Users/example/repo",
            "access_token=top-secret",
            "--access-token",
            "split-secret",
            "--password",
            "password-secret",
            "ordinary",
            f"prefix:{REPO_ROOT}/private",
        ]
        sanitized = v2_sanitized_argv(hostile)
        checks.check(
            "sensitive-argv-redacted",
            sanitized[0].startswith("<redacted:")
            and sanitized[1].startswith("<redacted:")
            and sanitized[2] == "--access-token"
            and sanitized[3].startswith("<redacted:")
            and sanitized[4] == "--password"
            and sanitized[5].startswith("<redacted:")
            and sanitized[6] == "ordinary"
            and sanitized[7].startswith("<redacted:")
            and all(
                secret
                not in canonical_bytes(sanitized).decode("utf-8")
                for secret in (
                    "top-secret",
                    "split-secret",
                    "password-secret",
                    str(REPO_ROOT),
                )
            ),
            expected={
                "equal_form": "redacted",
                "split_form": "option retained and value redacted",
                "absolute_or_embedded_repo_path": "redacted",
                "ordinary": "retained",
            },
            observed=sanitized,
        )
        checks.check(
            "split-redaction-deterministic-and-count-preserving",
            sanitized == v2_sanitized_argv(hostile)
            and len(sanitized) == len(hostile),
            expected={"deterministic": True, "argument_count": len(hostile)},
            observed={
                "deterministic": sanitized == v2_sanitized_argv(hostile),
                "argument_count": len(sanitized),
            },
        )
        body = b"secret stream body"
        receipt = {
            "bytes": len(body),
            "root": "sha256-v1:" + hashlib.sha256(body).hexdigest(),
            "body_retained": False,
        }
        checks.check(
            "raw-stream-root-only",
            "secret stream body" not in canonical_bytes(receipt).decode("utf-8")
            and receipt["body_retained"] is False,
            expected=False,
            observed=receipt,
        )
        diagnostic = (
            f"{REPO_ROOT}/private/input "
            "access_token=diagnostic-secret "
            + ("bounded-detail-" * 80)
        )
        summary = v2_bounded_diagnostic_summary(diagnostic)
        checks.check(
            "diagnostic-summary-redacted-bounded",
            "diagnostic-secret" not in summary
            and str(REPO_ROOT) not in summary
            and "<redacted>" in summary
            and "<truncated:sha256-v1:" in summary
            and len(summary.encode("utf-8"))
            <= V2_DIAGNOSTIC_SUMMARY_BYTES_CAP,
            expected={
                "credential": "redacted",
                "absolute_repo_path": "redacted",
                "bounded": True,
            },
            observed={
                "summary": summary,
                "bytes": len(summary.encode("utf-8")),
            },
        )
        mutated_state = {"phase": "before"}

        def mutate_then_refuse() -> None:
            mutated_state["phase"] = "after"
            raise InputRefused("synthetic refusal after forbidden mutation")

        guard_error = expect_error(
            EvidenceFailed,
            lambda: V2CheckCollector(
                "fixture-refusal-state",
                "fixture.refusal-state",
            ).refuses(
                "closure-mutated",
                InputRefused,
                mutate_then_refuse,
            ),
            contains="closure-mutated failed",
        )
        checks.check(
            "refusal-closure-mutation-detected",
            mutated_state["phase"] == "after"
            and guard_error.terminal == "EvidenceFailed",
            expected={
                "fixture_mutated": True,
                "collector_terminal": "EvidenceFailed",
            },
            observed={
                "fixture_mutated": mutated_state["phase"] == "after",
                "collector_terminal": guard_error.terminal,
                "diagnostic_root": text_root(str(guard_error)),
            },
        )
    elif slug == "log-order-terminal":
        payloads, _ = v2_synthetic_payloads(manifest)
        events = v2_read_event_stream(payloads["events.jsonl"])
        terminal = strict_json_loads(
            payloads["terminal.json"],
            label="synthetic terminal",
            require_canonical=True,
        )
        checks.check(
            "dense-unique-last-terminal",
            [event["sequence"] for event in events] == list(range(len(events)))
            and sum(event["terminal"] is not None for event in events) == 1
            and events[-1]["terminal"] == "Pass",
            expected=True,
            observed={
                "sequence": [event["sequence"] for event in events],
                "terminals": [
                    event["sequence"]
                    for event in events
                    if event["terminal"] is not None
                ],
            },
        )
        checks.check(
            "terminal-binds-event-roots",
            terminal["event_roots"] == [semantic_root(event) for event in events]
            and terminal["terminal_event_root"] == semantic_root(events[-1]),
            expected=terminal["event_roots"],
            observed=[semantic_root(event) for event in events],
        )
    elif slug in {"replay-review-offline", "replay-history-offline"}:
        before_receipts = len(_command_receipts)
        subject_mode = (
            "review-plan"
            if slug == "replay-review-offline"
            else "history-plan"
        )
        payloads, accepted_manifest, retained = v2_replayable_fixture_bundle(
            manifest,
            subject_mode=subject_mode,
        )
        terminal = strict_json_loads(
            payloads["terminal.json"],
            label="replayable fixture terminal",
            require_canonical=True,
        )
        events = v2_read_event_stream(payloads["events.jsonl"])
        reconstructed = v2_reconstruct_retained(
            artifact_root="target/v2-fixture",
            input_dir=f"{subject_mode}-run",
            payloads=payloads,
            terminal=terminal,
            events=events,
            accepted_manifest=accepted_manifest,
        )
        after_receipts = len(_command_receipts)
        checks.check(
            "artifact-only-reconstruction-exact",
            [row["semantic_root"] for row in reconstructed[:6]]
            == [row["semantic_root"] for row in retained[:6]]
            and reconstructed[6] == retained[6],
            expected=[row["semantic_root"] for row in retained[:6]],
            observed=[row["semantic_root"] for row in reconstructed[:6]],
        )
        checks.check(
            "selected-and-not-requested-projections",
            (
                reconstructed[3]["state"] == "POPULATED"
                and reconstructed[4]["state"] == "NOT_REQUESTED"
                if subject_mode == "review-plan"
                else reconstructed[3]["state"] == "NOT_REQUESTED"
                and reconstructed[4]["state"] == "POPULATED"
            ),
            expected=(
                ("POPULATED", "NOT_REQUESTED")
                if subject_mode == "review-plan"
                else ("NOT_REQUESTED", "POPULATED")
            ),
            observed=(
                reconstructed[3]["state"],
                reconstructed[4]["state"],
            ),
        )
        checks.check(
            "offline-no-command-calls",
            before_receipts == after_receipts,
            expected=before_receipts,
            observed=after_receipts,
        )
    elif slug == "replay-tamper-live-denied":
        payloads, accepted_manifest, _ = v2_replayable_fixture_bundle(
            manifest,
            subject_mode="review-plan",
        )
        terminal = strict_json_loads(
            payloads["terminal.json"],
            label="tamper fixture terminal",
            require_canonical=True,
        )
        events = v2_read_event_stream(payloads["events.jsonl"])
        before_receipts = len(_command_receipts)
        reconstructed = v2_reconstruct_retained(
            artifact_root="target/v2-fixture",
            input_dir="review-plan-run",
            payloads=payloads,
            terminal=terminal,
            events=events,
            accepted_manifest=accepted_manifest,
        )
        checks.check(
            "offline-baseline-no-live-or-network",
            len(reconstructed) == 7
            and len(_command_receipts) == before_receipts
            and reconstructed[0]["network_access"] is False
            and reconstructed[0]["direct_tracker_file_access"] is False,
            expected={
                "components": 7,
                "new_command_receipts": 0,
                "network_access": False,
                "direct_tracker_file_access": False,
            },
            observed={
                "components": len(reconstructed),
                "new_command_receipts": len(_command_receipts) - before_receipts,
                "network_access": reconstructed[0]["network_access"],
                "direct_tracker_file_access": reconstructed[0][
                    "direct_tracker_file_access"
                ],
            },
        )

        def reconstruct(
            candidate_payloads: Mapping[str, bytes],
            candidate_terminal: Mapping[str, Any] = terminal,
            candidate_events: Sequence[Mapping[str, Any]] = events,
        ) -> tuple[Any, ...]:
            return v2_reconstruct_retained(
                artifact_root="target/v2-fixture",
                input_dir="review-plan-run",
                payloads=candidate_payloads,
                terminal=candidate_terminal,
                events=candidate_events,
                accepted_manifest=accepted_manifest,
            )

        missing = dict(payloads)
        missing.pop("authority-v2.json")
        checks.refuses(
            "missing-artifact-refused",
            EvidenceFailed,
            lambda: reconstruct(missing),
            contains="membership differs",
        )
        extra = dict(payloads)
        extra["unlisted.json"] = canonical_bytes({"unlisted": True})
        checks.refuses(
            "extra-artifact-refused",
            EvidenceFailed,
            lambda: reconstruct(extra),
            contains="membership differs",
        )
        truncated = dict(payloads)
        truncated["inventory-v2.json"] = truncated["inventory-v2.json"][:-7]
        checks.refuses(
            "truncated-artifact-refused",
            InputRefused,
            lambda: reconstruct(truncated),
            contains="malformed JSON",
        )
        stale_root = strict_json_loads(
            payloads["inventory-v2.json"],
            label="tamper fixture inventory",
            require_canonical=True,
        )
        stale_root["no_claim"] = "mutated without replacing the retained root"
        stale_root_payloads = dict(payloads)
        stale_root_payloads["inventory-v2.json"] = canonical_bytes(stale_root)
        checks.refuses(
            "stale-semantic-root-refused",
            EvidenceFailed,
            lambda: reconstruct(stale_root_payloads),
            contains="semantic_root",
        )
        rerooted_inventory = v2_rooted(stale_root)
        rerooted_payloads = dict(payloads)
        rerooted_payloads["inventory-v2.json"] = canonical_bytes(
            rerooted_inventory
        )
        checks.refuses(
            "rerooted-mutated-artifact-refused",
            EvidenceFailed,
            lambda: reconstruct(rerooted_payloads),
            contains="terminal root differs at inventory_root",
        )
        v1_source = strict_json_loads(
            payloads["source-v2.json"],
            label="tamper fixture source",
            require_canonical=True,
        )
        v1_source["schema"] = SOURCE_SCHEMA
        v1_source = v2_rooted(v1_source)
        v1_confused_payloads = dict(payloads)
        v1_confused_payloads["source-v2.json"] = canonical_bytes(v1_source)
        checks.refuses(
            "v1-confused-source-refused",
            InputRefused,
            lambda: reconstruct(v1_confused_payloads),
            contains="unknown schema",
        )
        unsafe_terminal = dict(terminal)
        unsafe_terminal["optional_content_registry"] = [
            {
                "relative_path": "../escape.json",
            }
        ]
        unsafe_terminal = v2_rooted(unsafe_terminal)
        checks.refuses(
            "unsafe-optional-path-refused",
            InputRefused,
            lambda: reconstruct(
                payloads,
                candidate_terminal=unsafe_terminal,
            ),
            contains="unsafe",
        )
        extra_terminal_field = dict(terminal)
        extra_terminal_field["unexpected"] = "closed-schema violation"
        extra_terminal_field = v2_rooted(extra_terminal_field)
        checks.refuses(
            "terminal-extra-field-refused",
            InputRefused,
            lambda: reconstruct(
                payloads,
                candidate_terminal=extra_terminal_field,
            ),
            contains="non-closed schema",
        )
        non_green_terminal = dict(terminal)
        non_green_terminal.update(
            {
                "bundle_state": "COMPLETE_NON_GREEN",
                "terminal": "InputRefused",
                "exit_code": TERMINAL_EXIT["InputRefused"],
            }
        )
        non_green_terminal = v2_rooted(non_green_terminal)
        checks.refuses(
            "green-path-terminal-confusion-refused",
            EvidenceFailed,
            lambda: reconstruct(
                payloads,
                candidate_terminal=non_green_terminal,
            ),
            contains="complete-green seal",
        )
        reordered_event_payload = b"".join(
            canonical_bytes(row)
            for row in [events[1], events[0], *events[2:]]
        )
        checks.refuses(
            "reordered-event-stream-refused",
            EvidenceFailed,
            lambda: v2_read_event_stream(reordered_event_payload),
            contains="sequence/schema differs",
        )

        refusal_payloads, _ = v2_refusal_bundle_payloads(
            mode="review-plan",
            artifact_root="target/v2-fixture",
            artifact_dir="refusal-run",
            manifest=manifest,
            error=InputRefused("bounded in-memory replay refusal"),
            stage="selected_projection",
            available_roots={
                "source": None,
                "inventory": None,
                "authority": None,
                "review_plan": None,
                "history": None,
                "zero_sets": None,
            },
            argv=[str(SCRIPT_REL), "--review-plan"],
        )
        refusal_terminal = strict_json_loads(
            refusal_payloads["terminal.json"],
            label="tamper refusal terminal",
            require_canonical=True,
        )
        refusal_events = v2_read_event_stream(
            refusal_payloads["events.jsonl"],
            expected_terminal="InputRefused",
        )
        refusal_result = v2_validate_refusal_bundle(
            artifact_root="target/v2-fixture",
            input_dir="refusal-run",
            payloads=refusal_payloads,
            terminal=refusal_terminal,
            events=refusal_events,
            accepted_manifest=manifest,
        )
        checks.check(
            "non-green-baseline-preserved",
            refusal_result["terminal"] == "InputRefused"
            and refusal_result["exit_code"] == TERMINAL_EXIT["InputRefused"]
            and refusal_result["complete_green_prefix"] is False
            and refusal_result["replay_validated_without_output"] is True,
            expected={
                "terminal": "InputRefused",
                "green": False,
                "validated_without_output": True,
            },
            observed=refusal_result,
        )

        def validate_refusal(
            candidate_payloads: Mapping[str, bytes] = refusal_payloads,
            candidate_terminal: Mapping[str, Any] = refusal_terminal,
            candidate_events: Sequence[Mapping[str, Any]] = refusal_events,
        ) -> dict[str, Any]:
            return v2_validate_refusal_bundle(
                artifact_root="target/v2-fixture",
                input_dir="refusal-run",
                payloads=candidate_payloads,
                terminal=candidate_terminal,
                events=candidate_events,
                accepted_manifest=manifest,
            )

        def bind_refusal_terminal(
            candidate_payloads: Mapping[str, bytes],
            candidate_terminal: Mapping[str, Any],
        ) -> dict[str, bytes]:
            bound = dict(candidate_payloads)
            bound["terminal.json"] = canonical_bytes(candidate_terminal)
            return bound

        forged_failure = dict(refusal_terminal["failure_evidence"])
        forged_failure["result_category"] = "PASS"
        forged_failure = v2_rooted(forged_failure)
        forged_failure_terminal = dict(refusal_terminal)
        forged_failure_terminal["failure_evidence"] = forged_failure
        forged_failure_terminal["failure_root"] = forged_failure[
            "semantic_root"
        ]
        forged_failure_terminal = v2_rooted(forged_failure_terminal)
        checks.refuses(
            "rerooted-failure-category-refused",
            EvidenceFailed,
            lambda: validate_refusal(
                candidate_payloads=bind_refusal_terminal(
                    refusal_payloads,
                    forged_failure_terminal,
                ),
                candidate_terminal=forged_failure_terminal,
            ),
            contains="failure bindings disagree",
        )
        forged_terminal = dict(refusal_terminal)
        forged_terminal["no_claim"] = "this altered terminal claims Pass authority"
        forged_terminal = v2_rooted(forged_terminal)
        checks.refuses(
            "rerooted-refusal-terminal-contract-refused",
            EvidenceFailed,
            lambda: validate_refusal(
                candidate_payloads=bind_refusal_terminal(
                    refusal_payloads,
                    forged_terminal,
                ),
                candidate_terminal=forged_terminal,
            ),
            contains="terminal contract differs",
        )
        wrong_code_terminal = dict(refusal_terminal)
        wrong_code_terminal["exit_code"] = 0
        wrong_code_terminal = v2_rooted(wrong_code_terminal)
        checks.refuses(
            "refusal-terminal-exit-code-mismatch-refused",
            EvidenceFailed,
            lambda: validate_refusal(
                candidate_payloads=bind_refusal_terminal(
                    refusal_payloads,
                    wrong_code_terminal,
                ),
                candidate_terminal=wrong_code_terminal,
            ),
            contains="terminal contract differs",
        )
        forged_envelope_payloads = dict(refusal_payloads)
        forged_source_envelope = strict_json_loads(
            refusal_payloads["source-v2.json"],
            label="tamper refusal source envelope",
            require_canonical=True,
        )
        forged_source_envelope["available_projection_root"] = semantic_root(
            {"forged": "available source"}
        )
        forged_source_envelope = v2_rooted(forged_source_envelope)
        forged_envelope_payloads["source-v2.json"] = canonical_bytes(
            forged_source_envelope
        )
        forged_envelope_terminal = dict(refusal_terminal)
        forged_envelope_terminal["source_root"] = forged_source_envelope[
            "semantic_root"
        ]
        forged_identities = dict(
            forged_envelope_terminal["artifact_identities"]
        )
        forged_identities["source-v2.json"] = v2_artifact_identity(
            relative_path="source-v2.json",
            schema_kind=V2_REFUSAL_PROJECTION_SCHEMA,
            payload=forged_envelope_payloads["source-v2.json"],
        )
        forged_envelope_terminal["artifact_identities"] = forged_identities
        forged_envelope_terminal = v2_rooted(forged_envelope_terminal)
        forged_envelope_payloads = bind_refusal_terminal(
            forged_envelope_payloads,
            forged_envelope_terminal,
        )
        checks.refuses(
            "rerooted-refusal-envelope-binding-refused",
            EvidenceFailed,
            lambda: validate_refusal(
                candidate_payloads=forged_envelope_payloads,
                candidate_terminal=forged_envelope_terminal,
            ),
            contains="envelope bindings disagree",
        )
        forged_event_rows = [dict(row) for row in refusal_events]
        forged_event_rows[1]["result_category"] = "STARTED"
        forged_events_payload = b"".join(
            canonical_bytes(row) for row in forged_event_rows
        )
        forged_event_payloads = dict(refusal_payloads)
        forged_event_payloads["events.jsonl"] = forged_events_payload
        forged_event_terminal = dict(refusal_terminal)
        forged_event_terminal["events_content_root"] = (
            "sha256-v1:"
            + hashlib.sha256(forged_events_payload).hexdigest()
        )
        forged_event_terminal["event_roots"] = [
            semantic_root(row) for row in forged_event_rows
        ]
        forged_event_terminal["terminal_event_root"] = semantic_root(
            forged_event_rows[-1]
        )
        forged_event_identities = dict(
            forged_event_terminal["artifact_identities"]
        )
        forged_event_identities["events.jsonl"] = v2_artifact_identity(
            relative_path="events.jsonl",
            schema_kind=V2_EVENT_SCHEMA,
            payload=forged_events_payload,
        )
        forged_event_terminal[
            "artifact_identities"
        ] = forged_event_identities
        forged_event_terminal = v2_rooted(forged_event_terminal)
        forged_event_payloads = bind_refusal_terminal(
            forged_event_payloads,
            forged_event_terminal,
        )
        checks.refuses(
            "rerooted-refusal-event-contract-refused",
            EvidenceFailed,
            lambda: validate_refusal(
                candidate_payloads=forged_event_payloads,
                candidate_terminal=forged_event_terminal,
                candidate_events=forged_event_rows,
            ),
            contains="exact reconstruction",
        )

        def reroot_refusal_events(
            mutation: Callable[[list[dict[str, Any]]], None],
        ) -> tuple[dict[str, bytes], dict[str, Any], list[dict[str, Any]]]:
            rows = json.loads(canonical_bytes(refusal_events))
            mutation(rows)
            event_payload = b"".join(
                canonical_bytes(row) for row in rows
            )
            candidate_terminal = dict(refusal_terminal)
            candidate_terminal["events_content_root"] = (
                "sha256-v1:"
                + hashlib.sha256(event_payload).hexdigest()
            )
            candidate_terminal["event_count"] = len(rows)
            candidate_terminal["event_sequence"] = list(range(len(rows)))
            candidate_terminal["event_roots"] = [
                semantic_root(row) for row in rows
            ]
            candidate_terminal["terminal_event_root"] = semantic_root(
                rows[-1]
            )
            identities = dict(
                candidate_terminal["artifact_identities"]
            )
            identities["events.jsonl"] = v2_artifact_identity(
                relative_path="events.jsonl",
                schema_kind=V2_EVENT_SCHEMA,
                payload=event_payload,
            )
            candidate_terminal["artifact_identities"] = identities
            candidate_terminal = v2_rooted(candidate_terminal)
            candidate_payloads = dict(refusal_payloads)
            candidate_payloads["events.jsonl"] = event_payload
            candidate_payloads = bind_refusal_terminal(
                candidate_payloads,
                candidate_terminal,
            )
            parsed_rows = v2_read_event_stream(
                event_payload,
                expected_terminal="InputRefused",
            )
            return candidate_payloads, candidate_terminal, parsed_rows

        event_falsifiers: list[
            tuple[str, Callable[[list[dict[str, Any]]], None]]
        ] = [
            (
                "intermediate-first-divergence",
                lambda rows: rows[1].__setitem__(
                    "first_divergence",
                    "$.forged.intermediate",
                ),
            ),
            (
                "intermediate-recovery",
                lambda rows: rows[1].__setitem__(
                    "recovery",
                    "NOT_REQUIRED",
                ),
            ),
            (
                "case-id",
                lambda rows: rows[1].__setitem__(
                    "case_id",
                    "template-lint-v2.forged",
                ),
            ),
            (
                "assertion-id",
                lambda rows: rows[1].__setitem__(
                    "assertion_id",
                    "v2.case.forged",
                ),
            ),
            (
                "executor-id",
                lambda rows: rows[1].__setitem__(
                    "executor_id",
                    "v2.case.forged",
                ),
            ),
            (
                "parameter-root",
                lambda rows: rows[1].__setitem__(
                    "parameter_root",
                    semantic_root({"forged": "parameter"}),
                ),
            ),
            (
                "start-argv",
                lambda rows: rows[0].__setitem__(
                    "argv",
                    [str(SCRIPT_REL), "--history-plan"],
                ),
            ),
            (
                "later-argv",
                lambda rows: rows[1].__setitem__(
                    "argv",
                    ["forged"],
                ),
            ),
            (
                "prior-event-roots",
                lambda rows: rows[-1]["semantic_projection"].__setitem__(
                    "prior_event_roots",
                    [semantic_root({"forged": "prior"})],
                ),
            ),
        ]
        for falsifier_name, mutation in event_falsifiers:
            (
                candidate_payloads,
                candidate_terminal,
                candidate_events,
            ) = reroot_refusal_events(mutation)
            checks.refuses(
                f"rerooted-refusal-{falsifier_name}-refused",
                EvidenceFailed,
                lambda candidate_payloads=candidate_payloads,
                candidate_terminal=candidate_terminal,
                candidate_events=candidate_events: validate_refusal(
                    candidate_payloads=candidate_payloads,
                    candidate_terminal=candidate_terminal,
                    candidate_events=candidate_events,
                ),
                contains="exact reconstruction",
            )

        for field, forged_value in (
            ("artifact_root", "/absolute/forged"),
            ("artifact_root", "target/other-root"),
            ("artifact_dir", "../escape"),
            ("artifact_dir", "other-run"),
            ("replay_equivalence", {"forged": "equivalence"}),
            ("recovery", "MANUAL_RECOVERY_REQUIRED"),
        ):
            candidate_terminal = dict(refusal_terminal)
            candidate_terminal[field] = forged_value
            candidate_terminal = v2_rooted(candidate_terminal)
            candidate_payloads = bind_refusal_terminal(
                refusal_payloads,
                candidate_terminal,
            )
            checks.refuses(
                f"rerooted-refusal-terminal-{field}-{text_root(str(forged_value))[-8:]}",
                EvidenceFailed,
                lambda candidate_payloads=candidate_payloads,
                candidate_terminal=candidate_terminal: validate_refusal(
                    candidate_payloads=candidate_payloads,
                    candidate_terminal=candidate_terminal,
                ),
                contains="terminal contract differs",
            )
        changed = payloads["inventory-v2.json"] + b" "
        observed_identity = v2_artifact_identity(
            relative_path="inventory-v2.json",
            schema_kind=V2_INVENTORY_SCHEMA,
            payload=changed,
        )
        checks.check(
            "changed-artifact-identity-detected",
            observed_identity
            != terminal["artifact_identities"]["inventory-v2.json"],
            expected=terminal["artifact_identities"]["inventory-v2.json"],
            observed=observed_identity,
        )
        checks.check(
            "mixed-v1-schema-refused",
            RUN_TERMINAL_SCHEMA != V2_TERMINAL_SCHEMA,
            expected=V2_TERMINAL_SCHEMA,
            observed=RUN_TERMINAL_SCHEMA,
        )
    else:
        raise EvidenceFailed(f"no artifact executor for {slug}")
    return checks.finish(parameters)


def v2_failure_evidence(
    *,
    stage: str,
    detail: str,
    expected: Any = None,
    observed: Any = None,
    terminal: str = "EvidenceFailed",
    manifest_root: str | None = None,
    available_roots: Mapping[str, str | None] | None = None,
) -> dict[str, Any]:
    if terminal not in V2_SEMANTIC_REFUSAL_TERMINALS:
        raise EvidenceFailed("v2 failure evidence terminal is not semantic")
    divergence = (
        first_projection_divergence(expected, observed)
        if expected is not None or observed is not None
        else None
    )
    recovery = {
        "InputRefused": "CORRECT_INPUT_AND_RETRY_IN_FRESH_RUN_DIR",
        "NoData": "PROVIDE_REQUIRED_DATA_AND_RETRY_IN_FRESH_RUN_DIR",
        "EvidenceFailed": "MANUAL_RECOVERY_REQUIRED",
    }[terminal]
    normalized_roots = {
        key: (available_roots or {}).get(key)
        for key in (
            "source",
            "inventory",
            "authority",
            "review_plan",
            "history",
            "zero_sets",
        )
    }
    return v2_rooted(
        {
            "schema": V2_FAILURE_EVIDENCE_SCHEMA,
            "result_category": "SEMANTIC_REFUSAL",
            "stage": stage,
            "terminal": terminal,
            "exit_code": TERMINAL_EXIT[terminal],
            "diagnostic_code": f"{terminal}:{stage}",
            "detail_root": text_root(detail),
            "first_divergence": divergence or f"$.pipeline.{stage}",
            "recovery": recovery,
            "manifest_root": manifest_root,
            "available_roots": normalized_roots,
            "output_reserved": True,
            "complete_evidence_bundle": True,
            "complete_green_prefix": False,
            "retry_requires_fresh_run_dir": True,
            "no_claim": (
                "failure evidence identifies recovery work and never seals a "
                "partial or ambiguous publication as green"
            ),
        }
    )


def v2_execute_fault_resource_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "fault-resource-mutation", "slug": slug}
    inventory = v2_synthetic_inventory([v2_synthetic_target(0)])

    if slug == "mutation-forged-approval":
        forged = v2_synthetic_receipts(inventory, declared=True)
        forged_row = dict(forged["receipts"][0])
        forged_row["target_root"] = semantic_root({"forged": "stale-target"})
        forged_row = v2_rooted(forged_row)
        forged_document = dict(forged)
        forged_document["receipts"] = [forged_row]
        forged_document = v2_rooted(forged_document)
        checks.refuses(
            "stale-root-forged-approval",
            InputRefused,
            lambda: v2_derive_authority(
                inventory,
                forged_document,
                current_br_version="0.3.0",
                allow_mechanical_fixture=True,
            ),
            contains="exact source roots drifted",
        )
        untrusted = v2_synthetic_authority(
            inventory,
            declared=True,
            manual=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=False,
        )["decisions"][0]
        checks.check(
            "self-issued-receipts-never-mechanical",
            untrusted["readiness"] == "DECLARED_READY"
            and untrusted["remediation_route"] == "MANUAL_BR_REVIEW"
            and untrusted["external_authority"]["verified"] is False
            and untrusted["conditional_write_capability"]["verified"] is False,
            expected=("DECLARED_READY", "MANUAL_BR_REVIEW", False, False),
            observed=(
                untrusted["readiness"],
                untrusted["remediation_route"],
                untrusted["external_authority"]["verified"],
                untrusted["conditional_write_capability"]["verified"],
            ),
        )
        undeclared_receipts = v2_synthetic_receipts(
            inventory,
            manual=True,
        )
        checks.refuses(
            "undeclared-manual-authorization-refused",
            InputRefused,
            lambda: v2_derive_authority(
                inventory,
                undeclared_receipts,
                current_br_version="0.2.19",
            ),
            contains="manual authorization lacks",
        )

    elif slug == "mutation-forged-capability-deferred":
        for verdict in ("LYING", "NON_ATOMIC", "VERSION_MISMATCHED"):
            decision = v2_synthetic_authority(
                inventory,
                declared=True,
                external_verdict="VALID",
                conditional_verdict=verdict,
                gate_verdict="VALID",
                version="0.3.0",
                allow_mechanical_fixture=True,
            )["decisions"][0]
            checks.check(
                f"{verdict.lower()}-cannot-upgrade",
                decision["readiness"] != "MECHANICALLY_APPLY_ELIGIBLE"
                and decision["remediation_route"] != "AUTOMATED_CONDITIONAL",
                expected="non-mechanical",
                observed=(decision["readiness"], decision["remediation_route"]),
            )
        deferred_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0, status="deferred")]
        )
        deferred = v2_synthetic_authority(
            deferred_inventory,
            declared=True,
            manual=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=True,
        )["decisions"][0]
        checks.check(
            "deferred-never-upgrades",
            deferred["remediation_route"] == "ANALYSIS_ONLY"
            and deferred["deferred_apply_prohibition"] is True,
            expected=("ANALYSIS_ONLY", True),
            observed=(
                deferred["remediation_route"],
                deferred["deferred_apply_prohibition"],
            ),
        )

    elif slug == "mutation-missing-payload-edge":
        authority = v2_synthetic_authority(inventory)
        plan, _ = v2_build_review_plan(inventory, authority, max_targets=10)
        child = plan["children"][0]
        missing = dict(child)
        missing.pop("notes")
        missing = v2_rooted(missing)
        checks.refuses(
            "missing-required-payload-field",
            InputRefused,
            lambda: v2_validate_child_payload(missing),
            contains="non-closed schema",
        )
        membership = dict(child)
        membership["target_ids"] = [child["target_ids"][0], child["target_ids"][0]]
        membership["target_roots"] = [
            child["target_roots"][0],
            child["target_roots"][0],
        ]
        membership = v2_rooted(membership)
        checks.refuses(
            "duplicate-target-membership",
            EvidenceFailed,
            lambda: v2_validate_child_payload(membership),
            contains="target membership",
        )
        for label, edges in (
            (
                "missing-edge",
                child["intended_generated_edges"][:1],
            ),
            (
                "reversed-edge",
                [
                    {
                        **child["intended_generated_edges"][0],
                        "from": child["intended_generated_edges"][0]["to"],
                        "to": child["intended_generated_edges"][0]["from"],
                    },
                    child["intended_generated_edges"][1],
                ],
            ),
            (
                "duplicate-edge",
                [
                    child["intended_generated_edges"][0],
                    child["intended_generated_edges"][0],
                ],
            ),
            (
                "undeclared-edge",
                [
                    *child["intended_generated_edges"],
                    {
                        "from": "generated:extra",
                        "to": child["lane_parent"],
                        "type": "blocks",
                    },
                ],
            ),
        ):
            mutated = dict(child)
            mutated["intended_generated_edges"] = edges
            mutated = v2_rooted(mutated)
            checks.refuses(
                label,
                EvidenceFailed,
                lambda mutated=mutated: v2_validate_child_payload(mutated),
                contains="generated-edge",
            )

    elif slug == "mutation-relation-neighbor-drift":
        targets = [v2_synthetic_target(0), v2_synthetic_target(1)]
